    "คุณสมบัติเฉพาะ": "1. ความรู้พื้นฐานในการปฏิบัติราชการ (คะแนน 20 คะแนน จำนวน 10 ข้อ) 1.1 ความรู้เกี่ยวกับกฎหมายและระเบียบที่ใช้ในการปฏิบัติราชการ (1) พระราชบัญญัติข้อมูลข่าวสารของราชการ พ.ศ. 2540 (2) ระเบียบว่าด้วยการรักษาความลับของทางราชการ พ.ศ. 2544 และที่แก้ไขเพิ่มเติม (3) ระเบียบสำนักนายกรัฐมนตรีว่าด้วยงานสารบรรณ พ.ศ. 2526 และที่แก้ไขเพิ่มเติม (4) พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 (5) พระราชบัญญัติการปฏิบัติราชการทางอิเล็กทรอนิกส์ พ.ศ. 2565 1.2 ความรู้ความเข้าใจในบทบาท ภารกิจ หน้าที่ของกรมป่าไม้ 2. ความรู้ความสามารถในการปฏิบัติงานด้านวิชาการแผนที่ภาพถ่าย (คะแนน 180 คะแนน จำนวน 90 ข้อ) ได้แก่ 2.1 ความรู้เบื้องต้นเกี่ยวกับพื้นฐานระบบพิกัด มาตราส่วน และการคำนวณทางรังวัด - ระบบพิกัดแผนที่ (COORDINATES SYSTEM) และมาตราส่วนแผนที่ (MAP SCALE) - การคำนวณงานรังวัดและทำแผนที่ (SURVEYING COMPUTATION) - ความรู้พื้นฐานเกี่ยวกับเครื่องมือสำรวจทางภูมิศาสตร์ 2.2 การอ่าน แปล ตีความ ภาพถ่ายทางอากาศและภาพดาวเทียม (Photogrammetry & Remote Sensing) 2.3 ความรู้เบื้องต้นเกี่ยวกับระบบสารสนเทศภูมิศาสตร์ และการจัดการฐานข้อมูล (GIS & Spatial Data Management) - ความรู้เบื้องต้นเกี่ยวกับระบบสารสนเทศภูมิศาสตร์ (GIS) - ความรู้และแนวคิดเกี่ยวกับการออกแบบ จัดการ และสืบค้นฐานข้อมูลเชิงพื้นที่ - ความรู้เกี่ยวกับการใช้งานโปรแกรมสารสนเทศภูมิศาสตร์ 2.4 การประยุกต์ใช้ เทคโนโลยีเครือข่าย และภารกิจด้านป่าไม้ (Application & Implementation) - ระบบภูมิสารสนเทศผ่านเครือข่ายอินเทอร์เน็ต (Web GIS / Cloud-based) - การจัดทำข้อมูลแผนที่เชิงพื้นที่ในภารกิจงานแผนที่ภาพถ่ายของกรมป่าไม้ ด้วยระบบสารสนเทศภูมิศาสตร์",
    "รายละเอียดงาน": "ตามมาตรฐานกำหนดตำแหน่งนักวิชาการแผนที่ภาพถ่ายปฏิบัติการ",
