    "ตำแหน่ง": "นักวิชาการส่งเสริมการเกษตรปฏิบัติการ",
    "หน่วยงาน": "กรมส่งเสริมการเกษตร",
    "กระทรวง": "กระทรวงเกษตรและสหกรณ์",
    "ประเภทงาน": "ข้าราชการพลเรือน",
