    "จำนวนรับ": "100",
    "จังหวัด": "กรุงเทพมหานคร, กาญจนบุรี, จันทบุรี, ฉะเชิงเทรา, ชลบุรี, ชัยภูมิ, ตราด, นครพนม, นครราชสีมา, บึงกาฬ, ปราจีนบุรี, มุกดาหาร, ยโสธร, ร้อยเอ็ด, ศรีสะเกษ, สกลนคร, สระแก้ว, สุโขทัย, สุรินทร์, อำนาจเจริญ, อุดรธานี, อุบลราชธานี",
    "ระดับการศึกษา": "ป.ตรี | ได้รับปริญญาตรี หรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกันในสาขาวิชา ดังนี้\t\n\n-  สาขาวิชาเกษตรศาสตร์\n-  สาขาวิชาวิทยาศาสตร์ชีวภาพ ทางกีฏวิทยา ทางพฤกษศาสตร์ ทางชีววิทยา หรือทางเทคโนโลยีชีวภาพ\n-  สาขาวิชาวิทยาศาสตร์กายภาพ ทางภูมิศาสตร์ ทางภูมิศาสตร์กายภาพ ทางภูมิสารสนเทศศาสตร์ ทางเทคโนโลยีภูมิศาสตร์ หรือทางเทคโนโลยีภูมิสารสนเทศ \n-  สาขาวิชาคหกรรมศาสตร์\n-  สาขาวิชาวิทยาการสิ่งแวดล้อมและทรัพยากรธรรมชาติ \n-  สาขาวิชาเทคโนโลยีการผลิตพืช\n-  สาขาวิชาเทคโนโลยีอาหาร\n-  สาขาวิชาเทคโนโลยีชีวภาพ\n-  สาขาวิชาเศรษฐศาสตร์ ทางเศรษฐศาสตร์เกษตร\n-  สาขาวิชาบริหารธุรกิจ ทางการบริหารธุรกิจเกษตร\n-  สาขาวิชาเทคโนโลยีสิ่งแวดล้อม ทางเทคโนโลยีภูมิทัศน์\n",
    "วันเริ่มสมัคร": "2026-06-11",
    "วันหมดสมัคร": "2026-07-01",
    "วันสอบ": "",
    "วันสัมภาษณ์": "",
    "ลิงก์": "https://doae.thaijobjob.com",
    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10533.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/076.png",
    "คุณสมบัติเฉพาะ": "ทดสอบความรู้ความสามารถ โดยวิธีการสอบข้อเขียน ดังต่อไปนี้ - ความรู้เกี่ยวกับนโยบายและยุทธศาสตร์ด้านการพัฒนาการเกษตร เทคโนโลยีการผลิตพืช การจัดทำแผนพัฒนาการเกษตรของชุมชน การวางแผนส่งเสริมการผลิตสินค้าเกษตร นวัตกรรมทางการเกษตร การสร้างมูลค่าเพิ่ม ข้อมูลสถานการณ์การผลิต และการตลาดสินค้าเกษตร - ความรู้เกี่ยวกับการจัดการผลผลิตในพื้นที่ การจัดระบบเกษตรกรรม การถนอมอาหาร และแปรรูปผลผลิต การส่งเสริมธุรกิจเกษตร และอุตสาหกรรมเกษตร - ความรู้เกี่ยวกับการพัฒนาเกษตรกร องค์กรเกษตรกร วิสาหกิจชุมชน และเครือข่าย การถ่ายทอดเทคโนโลยีการเกษตร การจัดกระบวนการเรียนรู้และกระบวนการกลุ่มและเครือข่ายของเกษตรกร และการนำเทคโนโลยีสารสนเทศมาใช้ในงานส่งเสริมการเกษตร - ความรู้เกี่ยวกับการจัดการสิ่งแวดล้อมและเทคโนโลยีการเกษตรสมัยใหม่ - ความรู้เกี่ยวกับการเปลี่ยนแปลงของสภาพภูมิอากาศ - ความรู้เกี่ยวกับการใช้ระบบเครือข่ายการเชื่อมต่ออุปกรณ์อิเล็กทรอนิกส์กับอินเตอร์เน็ต (IOT) ในงานส่งเสริมการเกษตร - ความรู้เกี่ยวกับการนำเทคโนโลยีสารสนเทศมาใช้ในงานส่งเสริมการเกษตร - ความรู้เกี่ยวกับการทำการเกษตรตามแนวทางเศรษฐกิจพอเพียง เกษตรอินทรีย์ และเกษตรยั่งยืน",
    "รายละเอียดงาน": "ปฏิบัติงานวิชาการส่งเสริมการเกษตร ซึ่งมีลักษณะงานที่ปฏิบัติเกี่ยวกับการศึกษา วิเคราะห์วางแผน และวิจัยทางด้านส่งเสริมการเกษตร เช่น การส่งเสริมและพัฒนาการผลิตและการตลาด การพัฒนาระบบและวิธีการส่งเสริมการเกษตร การถ่ายทอดเทคโนโลยีการเกษตรและความรู้การเกษตร การจัดระบบ เกษตรกรรมและการแปรรูปเพื่อเพิ่มมูลค่าผลผลิต การส่งเสริมธุรกิจและอุตสาหกรรมเกษตร การส่งเสริมและพัฒนาเกษตรกร องค์กรเกษตรกรและวิสาหกิจชุมชน การจัดกระบวนการเรียนรู้และกระบวนการกลุ่มของเกษตรกร การพัฒนากลุ่มส่งเสริมอาชีพการเกษตร และพัฒนาครอบครัวเพื่อสร้างความเข้มแข็งของชุมชนเกษตร การให้บริการวิชาการด้านการจัดการการผลิตในพื้นที่ ให้คำปรึกษา แนะนำและบริการข้อมูลด้านการเกษตร และปฏิบัติหน้าที่อื่นตามที่ได้รับมอบหมาย (รายละเอียดเพิ่มเติมตามเอกสารแนบ)",
