    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10533.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/076.png",
    "คุณสมบัติเฉพาะ": "- นโยบายและยุทธศาสตร์ด้านการเกษตร - การออกแบบและพัฒนาระบบสารสนเทศ - ออกแบบฐานข้อมูลและการบริหารจัดการฐานข้อมูล (DBMS) - ความรู้เกี่ยวกับการพัฒนาระบบสารสนเทศ ปัญญาประดิษฐ์ (AI) แอปพลิเคชัน และเว็บไซต์ - ความรู้เกี่ยวกับระบบเครือข่ายคอมพิวเตอร์ - ความรู้เกี่ยวกับระบบเครือข่ายคอมพิวเตอร์และความมั่นคงปลอดภัยไซเบอร์ - การรักษาความมั่นคงปลอดภัยของข้อมูลและระบบเทคโนโลยีสารสนเทศ - พระราชบัญญัติว่าด้วยธุรกรรมทางอิเล็กทรอนิกส์ พ.ศ. 2544 และที่แก้ไขเพิ่มเติม - พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ.2562 (PDPA) - พระราชบัญญัติการปฏิบัติราชการทางอิเล็กทรอนิกส์ พ.ศ.๒๕๖๕ - ความรู้เกี่ยวกับการใช้เทคโนโลยีดิจิทัล (Digital Literacy)",
    "รายละเอียดงาน": "ปฏิบัติงานทางวิทยาการคอมพิวเตอร์ ซึ่งมีลักษณะงานที่ปฏิบัติเกี่ยวกับการศึกษา วิเคราะห์กำหนดคุณลักษณะของเครื่อง จัดระบบติดตั้ง เชื่อมโยงระบบเครื่องคอมพิวเตอร์ ศึกษา วิเคราะห์ ออกแบบเกี่ยวกับชุดคำสั่งระบบ ชุดคำสั่งประยุกต์ การจัดทำคู่มือการใช้คำสั่งต่าง ๆ กำหนดคุณลักษณะ ติดตั้งและใช้เครื่องมือชุดคำสั่งสื่อสาร การจัดและบริหารระบบสารสนเทศ รวมทั้งการดำเนินการเกี่ยวกับการกระทำผิด ทางคอมพิวเตอร์ และธุรกรรมอิเล็กทรอนิกส์ การให้คำปรึกษาแนะนำ อบรมเกี่ยวกับวิทยาการคอมพิวเตอร์ด้านต่าง ๆ แก่บุคคลหรือหน่วยงานที่เกี่ยวข้อง ติดตามความก้าวหน้าของเทคโนโลยีใหม่ ๆ และปฏิบัติหน้าที่อื่นตามที่ได้รับมอบหมาย (รายละเอียดเพิ่มเติมตามเอกสารที่แนบ)",
