    "รายละเอียดงาน": "1. ปฏิบัติภารกิจด้านการใช้วิชาการทางด้านสถิติ เช่น การกำหนดมาตรฐานสถิติ กำหนดระเบียบวิธีปฏิบัติและควบคุมคุณภาพเชิงสถิติ และเทคนิคการปฏิบัติทางการสถิติ การวางแผนจัดการสถิติ รวมทั้ง การดำเนินการส่งเสริมวิชาการทางด้านสถิติ และปฏิบัติหน้าที่ที่เกี่ยวข้อง โดยมีคู่มือหรือแนวปฏิบัติ หรือคำสั่งอย่างกว้าง ๆ และอยู่ภายใต้การกำกับตรวจสอบเฉพาะกรณีที่จำเป็น 2. ปฏิบัติงานสนามเก็บรวบรวมข้อมูลในพื้นที่จังหวัดฉะเชิงเทราได้ทุกอำเภอ ตำบล หมู่บ้าน มีทักษะการใช้เครื่อง Tablet และคอมพิวเตอร์ 3. ปฏิบัติภารกิจหรือประสานงานกับหน่วยงานของรัฐและเอกชนที่เกี่ยวข้องกับการพัฒนา ด้านดิจิทัลเพื่อพัฒนาเป็นจังหวัดที่มีศักยภาพในการให้บริการภาครัฐ ที่ประชาช สามารถเข้าถึงได้ด้วยเทคโนโลยีดิจิทัล 4. ปฏิบัติภารกิจเพื่อสนับสนุนการขับเคลื่อนนโยบายที่สำคัญตามนโยบายของกระทรวงดิจิทัลเพื่อเศรษฐกิจและสังคม 5. ปฏิบัติงานเกี่ยวกับงานธุรการต่าง ๆ เช่น การรับ – ส่ง งานในระบบสารบรรณ การจัดทำหนังสือราชการต่าง ๆ 6. ปฏิบัติหน้าที่อื่นตามที่ได้รับมอบหมายเพื่อสนับสนุนภารกิจหลักและภารกิจอื่น ๆ ของสำนักงานสถิติจังหวัดฉะเชิงเทรา",
