    "รายละเอียดงาน": "(๑) ดำเนินการเกี่ยวกับการเสนอความเห็นแก่ผู้บังคับบัญชาในการตอบข้อหารือหรือวินิจฉัยปัญหากฎหมายที่เกี่ยวข้องกับระเบียบของทางราชการที่มีผลกระทบต่อการดำเนินงานของสำนักงานฯ เพื่อเป็นข้อมูลสนับสนุนการพิจารณาของผู้บังคับบัญชา (๒) ดำเนินการด้านการศึกษา วิเคราะห์ และวิจัย เพื่อปรับปรุงกฎหมาย และระเบียบเกี่ยวกับสำนักงานฯ ที่รับผิดชอบ เพื่อให้ทันกับสถานการณ์ และอำนวยความสะดวกในการทำงานโดยพิจารณา ถึงความเหมาะสมและเป็นธรรมกับทุกฝ่าย (๓) ร่วมดำเนินการด้านการศึกษาข้อมูล รวบรวมแสวงหาข้อเท็จจริงและข้อกฎหมาย เสนอความเห็นในการดำเนินการเรื่องใดๆ ที่เกี่ยวข้องกับวินัยข้าราชการ การร้องทุกข์ การพิทักษ์ระบบคุณธรรม รวมถึงการดำเนินการใดๆ ตามกฎหมายปกครองที่เกี่ยวข้องกับการบริหารราชการ และการดำเนินคดี ของสำนักงานฯ เพื่อใช้เป็นแนวทางในการปฏิบัติงาน และสามารถดำเนินการได้อย่างถูกต้อง (๔) ร่วมอำนวยการประชุมคณะกรรมการด้านกฎหมาย และด้านอื่นๆ ที่เกี่ยวข้องเพื่อจัดประชุมเสนอความเห็น จัดทำระเบียบวาระการประชุม และรายงานการประชุม (๕) ปฏิบัติงานหรือร่วมปฏิบัติงานของสำนักงานฯตามที่ได้รับมอบหมาย",
