    "คุณสมบัติเฉพาะ": "ได้รับคุณวุฒิอย่างใดอย่างหนึ่ง ดังต่อไปนี้ ๑. ประกาศนียบัตรมัธยมศึกษาตอนต้น 2. ประกาศนียบัตรมัธยมศึกษาตอนปลาย 3. ประกาศนียบัตรวิชาชีพ (ปวช.) 4. ประกาศนียบัตรวิชาชีพเทคนิค (ปวท.) 5. ประกาศนียบัตรวิชาชีพชั้นสูง (ปวส.)",
    "รายละเอียดงาน": "(๑) ปฏิบัติงานด้านธุรการ งานสารบรรณ งานบริหารทั่วไป เช่น การรับส่งหนังสือ ลงทะเบียนร่างหนังสือโต้ตอบ ร่วมอำนวยการประชุม การบันทึกข้อมูล เพื่อสนับสนุนงานด้านต่างๆ ให้ดำเนินการไปด้วยความสะดวก รวดเร็วและบรรลุวัตถุประสงค์ของสำนักงานฯ (๒) ปฏิบัติงานในการรวบรวมข้อมูล จัดเก็บสถิติการดำเนินงานด้านต่างๆ เอกสารหลักฐานทางราชการที่เกี่ยวข้องกับการปฏิบัติงาน ให้ถูกต้อง เป็นหมวดหมู่ และสะดวกในการค้นหาเพื่อสนับสนุน การทำงานให้มีประสิทธิภาพ (๓) ส่งเสริม สนับสนุนการปฏิบัติงานด้านการบริหารพัสดุ สินทรัพย์ และการรวบรวมเอกสารเบิกจ่ายเงินของสำนักงานฯ (๔) ปฏิบัติงานด้านการเผยแพร่ ประชาสัมพันธ์ เกี่ยวกับข้อมูล และผลการดำเนินงานด้านต่างๆ ของสำนักงานฯ (๕) อำนวยความสะดวกในการปฏิบัติงานด้านต่างๆ ของสำนักงานฯ เพื่อให้ได้ผลการดำเนินงานบรรลุตามเป้าหมายที่สำนักงานฯกำหนด (๖) ปฏิบัติงานหรือร่วมปฏิบัติงานของสำนักงานฯ ตามที่ได้รับมอบหมาย",
