    "คุณสมบัติเฉพาะ": "1. มีความรู้ในระบบสาธารณสุขและระบบหลักประกันสุขภาพถ้วนหน้า 2. มีความรู้เชิงวิชาการในการบริหารกองทุน การพัฒนาคุณภาพบริการ/หน่วยบริการ 3. มีความรู้ ทักษะในการพัฒนาระบบการชดเชย การบริหารระบบการเงิน การคลังการบริหารจัดการรายโรค 4. มีความรู้ทักษะในการวิเคราะห์ วางแผน การจัดการ การประเมินผลเพื่อการตัดสินใจ 5. มีความสามารถในการใช้คอมพิวเตอร์ Microsoft/โปรแกรมสำเร็จรูปต่าง ๆ ที่เกี่ยวข้อง",
    "รายละเอียดงาน": "รับผิดชอบต่อความสำเร็จของสำนักและขององค์กร โดยวางแผนเชิงกลยุทธ์ พัฒนา บริหารจัดการ สำนักในความรับผิดชอบ ให้เชื่อมโยงและดำเนินไปในในทิศทางหรือตามนโยบายขององค์กร เพื่อเป็นกลไกสำคัญในการขับเคลื่อนองค์กรให้บรรลุเป้าหมาย สามารถสร้างวิสัยทัศน์ กำหนดแนวทางในการปฏิบัติงาน และให้คำปรึกษาแนะนำแก่บุคลากรของสำนัก เพื่อให้บรรลุตามวิสัยทัศน์และภารกิจขององค์กรได้",
