    "จำนวนรับ": "33",
    "จังหวัด": "กาญจนบุรี, ขอนแก่น, จันทบุรี, ฉะเชิงเทรา, ชลบุรี, ชัยนาท, เชียงราย, เชียงใหม่, ตรัง, นครศรีธรรมราช, นนทบุรี, นราธิวาส, ปทุมธานี, ปราจีนบุรี, เพชรบูรณ์, ระยอง, ลพบุรี, ลำพูน, สกลนคร, สระแก้ว, สระบุรี, สิงห์บุรี, อำนาจเจริญ",
