    "ลิงก์": "https://moph.jobthaigov.com/",
    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10464.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/161.png",
    "คุณสมบัติเฉพาะ": "1) ความรู้เบื้องต้นทางด้านการเงินและบัญชี 2) ความรู้เกี่ยวกับพระราชบัญญัติวินัยการเงินการคลัง ของรัฐ พ.ศ. 2561 3) ความรู้เกี่ยวกับระเบียบกระทรวงการคลังว่าด้วยการเบิกเงินจากคลัง การรับเงิน การจ่ายเงิน การเก็บรักษาเงิน และการนำเงินส่งคลัง พ.ศ. 2562 และที่แก้ไขเพิ่มเติม 4) ความรู้เกี่ยวกับระเบียบกระทรวงการคลังว่าด้วย เงินทดรองราชการ พ.ศ. 2562 5) ความรู้เกี่ยวกับระเบียบกระทรวงการคลังว่าด้วยการเบิกจ่ายค่าใช้จ่ายในการบริหารงานของส่วนราชการ พ.ศ. 2553 6) ความรู้เกี่ยวกับระเบียบกระทรวงสาธารณสุขว่าด้วย เงินบำรุงของหน่วยบริการในสังกัดกระทรวงสาธารณสุข พ.ศ. 2562 และที่แก้ไขเพิ่มเติม 7) ความรู้เกี่ยวกับพระราชบัญญัติประกันสุขภาพแห่งชาติ พ.ศ. 2545 8) ความรู้เกี่ยวกับพระราชบัญญัติประกันสังคม พ.ศ. 2533 และที่แก้ไขเพิ่มเติม 9) ความรู้เกี่ยวกับการใช้งานคอมพิวเตอร์และกฎหมายที่เกี่ยวข้อง ได้แก่ พระราชบัญญัติว่าด้วยการกระทำความผิดเกี่ยวกับคอมพิวเตอร์ พ.ศ. 2550 และที่แก้ไขเพิ่มเติม พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 และพระราชบัญญัติการปฏิบัติราชการทางอิเล็กทรอนิกส์ พ.ศ. 2565 10) ความรู้เกี่ยวกับวิสัยทัศน์ พันธกิจ โครงสร้าง อำนาจหน้าที่ ภารกิจ นโยบายและยุทธศาสตร์ของสำนักงานปลัดกระทรวงสาธารณสุขและกระทรวงสาธารณสุข",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ซึ่งไม่จำเป็นต้องใช้ผู้สำเร็จการศึกษาระดับปริญญา ปฏิบัติงานด้านการเงินและบัญชี ตามแนวทาง แบบอย่าง ขั้นตอน และวิธีการที่ชัดเจน ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย",
