    "ระดับการศึกษา": "ปวส., อนุปริญญา | ได้รับประกาศนียบัตรวิชาชีพชั้นสูงหรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกัน \nในสาขาวิชาโยธา สาขาวิชาสำรวจ หรือสาขาวิชาการก่อสร้าง หรือ ได้รับอนุปริญญาหลักสูตร 3 ปี หรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกัน ในสาขาวิชาใดสาขาวิชาหนึ่ง ทางโยธา ทางสำรวจ หรือทางการก่อสร้าง",
    "วันเริ่มสมัคร": "2026-05-25",
