    "ลิงก์": "https://moph.jobthaigov.com/",
    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10464.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/161.png",
    "คุณสมบัติเฉพาะ": "1) ความรู้เกี่ยวกับการสำรวจ การออกแบบ การเขียนแบบ การประมาณราคา การปรับปรุง และซ่อมแซม 2) ความรู้เกี่ยวกับการบริหารงานก่อสร้าง การควบคุมงานก่อสร้าง การอำนวยความปลอดภัย ในงานก่อสร้าง 3) ความรู้พื้นฐานด้านกฎหมายและสัญญาก่อสร้าง การตรวจการจ้างตามที่ได้รับมอบหมาย 4) ความรู้เกี่ยวกับการทดสอบวัสดุ ปฐพีกลศาสตร์ และคอนกรีตเทคโนโลยี 5) ความรู้เกี่ยวกับการใช้งานคอมพิวเตอร์และกฎหมายที่เกี่ยวข้อง ได้แก่ พระราชบัญญัติ ว่าด้วยการกระทำความผิดเกี่ยวกับคอมพิวเตอร์ พ.ศ. 2550 และที่แก้ไขเพิ่มเติม พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 และพระราชบัญญัติการปฏิบัติราชการ ทางอิเล็กทรอนิกส์ พ.ศ. 2565 6) ความรู้เกี่ยวกับวิสัยทัศน์ พันธกิจ โครงสร้าง อำนาจหน้าที่ ภารกิจ นโยบายและยุทธศาสตร์ ของสำนักงานปลัดกระทรวงสาธารณสุขและกระทรวงสาธารณสุข",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ซึ่งไม่จำเป็นต้องใช้ผู้สำเร็จการศึกษาระดับปริญญา ปฏิบัติงานด้านช่างโยธา ตามแนวทาง แบบอย่าง ขั้นตอน และวิธีการที่ชัดเจน ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย",
