    "จังหวัด": "กระบี่, ชลบุรี, ชัยนาท, เชียงราย, เชียงใหม่, ตรัง, ตราด, นครปฐม, นนทบุรี, นราธิวาส, ประจวบคีรีขันธ์, พระนครศรีอยุธยา, พัทลุง, พิษณุโลก, เพชรบูรณ์, แพร่, ภูเก็ต, แม่ฮ่องสอน, ราชบุรี, ลพบุรี, ลำพูน, สมุทรปราการ, สมุทรสงคราม, สุราษฎร์ธานี, อำนาจเจริญ, อุทัยธานี",
    "ระดับการศึกษา": "ป.ตรี | ได้รับปริญญาตรีหรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกัน ในสาขาวิชาใดสาขาวิชาหนึ่ง ทางจิตวิทยา \nสาขาวิชาสาธารณสุขศาสตร์ สาขาวิชาพยาบาลศาสตร์ \nสาขาวิชาวิทยาศาสตร์ชีวภาพ สาขาวิชาวิทยาศาสตร์กายภาพ สาขาวิชาแพทยศาสตร์ สาขาวิชาทันตแพทยศาสตร์ สาขาวิชาเทคนิคการแพทย์ สาขาวิชาวิทยาศาสตร์ประยุกต์ สาขาวิชาวิทยาศาสตร์การแพทย์ สาขาวิชาเภสัชศาสตร์ สาขาวิชาเกษตรศาสตร์ สาขาวิชาคหกรรมศาสตร์ สาขาวิชาสังคมสงเคราะห์ศาสตร์ สาขาวิชาสังคมศาสตร์ \nและพฤติกรรมศาสตร์ สาขาวิชาการแพทย์แผนไทย \nสาขาวิชาการแพทย์แผนไทยประยุกต์ สาขาวิชาเทคโนโลยีชีวภาพ สาขาวิชาเทคโนโลยีสิ่งแวดล้อม สาขาวิชาวิทยาการสิ่งแวดล้อมและทรัพยากรธรรมชาติ สาขาวิชาคณิตศาสตร์และสถิติ สาขาวิชาศึกษาศาสตร์ ทางพลศึกษา \nหรือทางสุขศึกษา สาขาวิชาวิศวกรรมศาสตร์ ทางวิศวกรรมสิ่งแวดล้อม หรือทางวิศวกรรมสุขาภิบาล \nสาขาวิชาเศรษฐศาสตร์ ทางเศรษฐศาสตร์สาธารณสุข \nหรือสาขาวิชากายภาพบำบัด",
