    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/161.png",
    "คุณสมบัติเฉพาะ": "1) ความรู้ความสามารถพื้นฐานด้านสาธารณสุข ดังนี้ - การประเมินสุขภาพและการวินิจฉัยอนามัยชุมชน - การวางแผนแก้ไขปัญหาสาธารณสุขชุมชน และการติดตามประเมินผล - ระบบข้อมูลข่าวสารและสารสนเทศ - การคุ้มครองผู้บริโภคด้านสาธารณสุข - ประชากรศาสตร์ - เศรษฐศาสตร์สาธารณสุข - ชีวสถิติ 2) ความรู้ความสามารถ ทักษะ สมรรถนะ การประยุกต์ความรู้ทางด้านสาธารณสุข ดังนี้ - สถิติและการวิจัยทางด้านสาธารณสุข - ระบาดวิทยา การป้องกันและการควบคุมโรค - บริหารสาธารณสุข - อนามัยสิ่งแวดล้อม - อาชีวอนามัยและความปลอดภัยในการทำงาน - กฎหมายและจรรยาบรรณวิชาชีพการสาธารณสุข - การตรวจประเมิน การบำบัดโรคเบื้องต้น การดูแลช่วยเหลือฟื้นฟูสภาพ และการส่งต่อ - การส่งเสริมสุขภาพ - สุขศึกษาและพฤติกรรมศาสตร์ 3) ความรู้เกี่ยวกับนโยบายของรัฐด้านการสาธารณสุข 4) ความรู้เกี่ยวกับสถานการณ์ปัจจุบันของระบบสาธารณสุขและสุขภาพ 5) ความรู้เกี่ยวกับแผนการปฏิรูปประเทศด้านสาธารณสุข 6) ความรู้เกี่ยวกับการใช้งานคอมพิวเตอร์และกฎหมายที่เกี่ยวข้อง ได้แก่ พระราชบัญญัติว่าด้วยการกระทำความผิดเกี่ยวกับคอมพิวเตอร์ พ.ศ. 2550 และที่แก้ไขเพิ่มเติม พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 และพระราชบัญญัติการปฏิบัติราชการทางอิเล็กทรอนิกส์ พ.ศ. 2565 7) ความรู้เกี่ยวกับวิสัยทัศน์ พันธกิจ โครงสร้าง อำนาจหน้าที่ ภารกิจ นโยบายและยุทธศาสตร์ของสำนักงานปลัดกระทรวงสาธารณสุขและกระทรวงสาธารณสุข",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ที่ต้องใช้ความรู้ ความสามารถทางวิชาการในการทำงาน ปฏิบัติงานด้านวิชาการสาธารณสุข ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย",
