    "คุณสมบัติเฉพาะ": "1) ความรู้เกี่ยวกับพระราชบัญญัติวิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539 และที่แก้ไขเพิ่มเติม 2) ความรู้เกี่ยวกับพระราชบัญญัติความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539 3) ความรู้เกี่ยวกับพระราชบัญญัติข้อมูลข่าวสารของราชการ พ.ศ. 2540 4) ความรู้เกี่ยวกับประมวลกฎหมายอาญา 5) ความรู้เกี่ยวกับประมวลกฎหมายแพ่งและพาณิชย์ 6) ความรู้เกี่ยวกับกฎหมายข้าราชการและการดำเนินการวินัยข้าราชการตามพระราชบัญญัติ ระเบียบข้าราชการพลเรือน พ.ศ. 2551 และที่แก้ไขเพิ่มเติม 7) ความรู้เกี่ยวกับพระราชบัญญัติจัดตั้งศาลปกครองและวิธีพิจารณาคดีปกครอง พ.ศ. 2542 และที่แก้ไขเพิ่มเติม 8) ความรู้เกี่ยวกับระเบียบกระทรวงสาธารณสุขว่าด้วยเงินบำรุงของหน่วยบริการในสังกัดกระทรวงสาธารณสุข พ.ศ. 2562 และที่แก้ไขเพิ่มเติม 9) ความรู้เกี่ยวกับระเบียบกระทรวงสาธารณสุขว่าด้วยเงินบริจาคและทรัพย์สินบริจาคของหน่วยบริการ พ.ศ. 2561 10) ความรู้เกี่ยวกับการใช้งานคอมพิวเตอร์และกฎหมายที่เกี่ยวข้อง ได้แก่ พระราชบัญญัติว่าด้วยการกระทำความผิดเกี่ยวกับคอมพิวเตอร์ พ.ศ. 2550 และที่แก้ไขเพิ่มเติม พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 และพระราชบัญญัติการปฏิบัติราชการทางอิเล็กทรอนิกส์ พ.ศ. 2565 11) ความรู้เกี่ยวกับวิสัยทัศน์ พันธกิจ โครงสร้าง อำนาจหน้าที่ ภารกิจ นโยบายและยุทธศาสตร์ของสำนักงานปลัดกระทรวงสาธารณสุขและกระทรวงสาธารณสุข",
