    "คุณสมบัติเฉพาะ": "1) ความรู้เกี่ยวกับระเบียบสำนักนายกรัฐมนตรีว่าด้วยงานสารบรรณ พ.ศ. 2526 และที่แก้ไขเพิ่มเติม 2) ความรู้เกี่ยวกับระเบียบว่าด้วยการรักษาความลับของทางราชการ พ.ศ. 2544 และที่แก้ไขเพิ่มเติม 3) ความรู้เกี่ยวกับพระราชบัญญัติข้อมูลข่าวสารของราชการ พ.ศ. 2540 4) ความรู้เกี่ยวกับพระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 5) ความรู้เกี่ยวกับการจัดการสำนักงาน 6) ความรู้เกี่ยวกับระเบียบสำนักนายกรัฐมนตรีว่าด้วยรถราชการ พ.ศ. 2523 และที่แก้ไขเพิ่มเติม 7) ความรู้เกี่ยวกับการใช้งานคอมพิวเตอร์และกฎหมายที่เกี่ยวข้อง ได้แก่ พระราชบัญญัติ ว่าด้วยการกระทำความผิดเกี่ยวกับคอมพิวเตอร์ พ.ศ. 2550 และที่แก้ไขเพิ่มเติม พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 และพระราชบัญญัติการปฏิบัติราชการ ทางอิเล็กทรอนิกส์ พ.ศ. 2565 8) ความรู้เกี่ยวกับวิสัยทัศน์ พันธกิจ โครงสร้าง อำนาจหน้าที่ ภารกิจ นโยบายและยุทธศาสตร์ ของสำนักงานปลัดกระทรวงสาธารณสุขและกระทรวงสาธารณสุข",
