    "รายละเอียดงาน": "ช่วยปฏิบัติงานด้านวิชาการประมง และช่วยปฏิบัติงานจัดเตรียม ดูแลรักษาเครื่องมือ อุปกรณ์ เคมีภัณฑ์ ที่ใช้ในการปฏิบัติงานด้านวิทยาศาสตร์และเทคโนโลยี รวมทั้งจัดทำทะเบียนการเบิกจ่ายวัสดุ และเคมีภัณฑ์ เพื่อให้สามารถนำไปใช้ได้อย่างถูกต้องเหมาะสม วิเคราะห์ทดสอบ สอบเทียบ วิจัยเบื้องต้น และช่วยรวบรวมข้อมูลเพื่อให้นักวิชาการสามารถทำงานได้อย่างรวดเร็ว และปฏิบัติงานอื่น ๆ ที่เกี่ยวข้องตามที่ได้รับมอบหมาย",
