    "ระดับการศึกษา": "ปวส., อนุปริญญา | ได้รับประกาศนียบัตรวิชาชีพชั้นสูง (ปวส.) หรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกัน ในทุกสาขาวิชา หรืออนุปริญญาหลักสูตร 3 ปี หรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกันในทุกสาขาวิชา",
