    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/007.png",
    "คุณสมบัติเฉพาะ": "- พระราชบัญญัติข้อมูลข่าวสารของราชการ พ.ศ. 2540 - พระราชบัญญัติระเบียบข้าราชการพลเรือน พ.ศ. 2551 และที่แก้ไขเพิ่มเติม - พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 - พระราชบัญญัติการปฏิบัติราชการทางอิเล็กทรอนิกส์ พ.ศ. 2565 - ระเบียบสำนักนายกรัฐมนตรีว่าด้วยงานสารบรรณ พ.ศ. 2526 และที่แก้ไขเพิ่มเติม - ระเบียบว่าด้วยการรักษาความลับของทางราชการ พ.ศ. 2544 และที่แก้ไขเพิ่มเติม",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ซึ่งไม่จำเป็นต้องใช้ผู้สำเร็จการศึกษาระดับปริญญา ปฏิบัติงานด้านธุรการ ตามแนวทาง แบบอย่าง ขั้นตอน และวิธีการที่ชัดเจน ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ 1. ด้านการปฏิบัติการ (1) ปฏิบัติงานธุรการ งานสารบรรณ งานบริการทั่วไป เช่น การรับส่ง ลงทะเบียน ร่างหนังสือโต้ตอบ จัดเตรียมการประชุม การบันทึกข้อมูล เพื่อสนับสนุนให้งานต่าง ๆ ดำเนินไปได้ โดยสะดวกราบรื่นและมีหลักฐานตรวจสอบได้ (2) รวบรวมข้อมูล จัดเก็บข้อมูลสถิติ เอกสาร หลักฐานหนังสือ ตามระเบียบวิธีปฏิบัติ เพื่อสะดวกต่อการค้นหา และเป็นหลักฐานทางราชการ (3) ดำเนินการเกี่ยวกับพัสดุ ครุภัณฑ์ของสำนักงาน เพื่อให้มีอุปกรณ์ที่มีคุณภาพไว้ใช้งานและอยู่ในสภาพพร้อมใช้งาน (4) รวบรวมรายงานผลการปฏิบัติงานและข้อมูลต่าง ๆ นำเสนอต่อผู้บังคับบัญชา เพื่อนำไปใช้เสนอแนะและปรับปรุงการปฏิบัติงานต่อไป 2. ด้านการบริการ (1) ติดต่อประสานงานกับบุคคลภายในหน่วยงานเดียวกันหรือหน่วยงานที่เกี่ยวข้อง เพื่อให้การปฏิบัติงานเป็นไปด้วยความราบรื่น (2) ให้บริการข้อมูลแก่ผู้มาติดต่อราชการ เพื่อให้ได้รับข้อมูลที่จะนำไปใช้ประโยชน์ได้ต่อไป (3) ผลิตเอกสารต่าง ๆ เพื่อสนับสนุนการปฏิบัติงานตามภารกิจของหน่วยงาน และปฏิบัติหน้าที่อื่นที่เกี่ยวข้องตามที่ได้รับมอบหมาย ทั้งนี้ การปฏิบัติงานในตำแหน่งดังกล่าวอาจมีภารกิจที่จะต้องอยู่ปฏิบัติงานนอกเหนือเวลาราชการเป็นเวลาบ่อยครั้ง โดยเฉพาะในช่วงจัดเตรียม วิเคราะห์ และจัดทำงบประมาณรายจ่ายประจำปี บริหารงบประมาณ ติดตามและประเมินผลการใช้จ่ายเงินงบประมาณ ตามที่ผู้บังคับบัญชามอบหมาย และ/หรือสามารถไปปฏิบัติงานประจำในต่างจังหวัดได้",
