    "คุณสมบัติเฉพาะ": "- พระราชบัญญัติวินัยการเงินการคลังของรัฐ พ.ศ. 2561 - พระราชกฤษฎีกาค่าใช้จ่ายในการเดินทางไปราชการ พ.ศ. 2526 และที่แก้ไขเพิ่มเติม - ระเบียบกระทรวงการคลังว่าด้วยการเบิกค่าใช้จ่ายในการเดินทางไปราชการ พ.ศ. 2550 และที่แก้ไขเพิ่มเติม - ระเบียบกระทรวงการคลังว่าด้วยการเบิกเงินจากคลัง การรับเงิน การจ่ายเงิน การเก็บรักษาเงิน และการนำส่งคลัง พ.ศ. 2562 - ระเบียบกระทรวงการคลังว่าด้วยการเบิกค่าใช้จ่ายในการบริหารงานของส่วนราชการ พ.ศ. 2553 - ระเบียบกระทรวงการคลังว่าด้วยค่าใช้จ่ายในการฝึกอบรม การจัดงาน และการประชุมระหว่างประเทศ พ.ศ. 2549 และที่แก้ไขเพิ่มเติม",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ซึ่งไม่จำเป็นต้องใช้ผู้สำเร็จการศึกษาระดับปริญญา ปฏิบัติงานด้านการเงินและบัญชี ตามแนวทาง แบบอย่าง ขั้นตอน และวิธีการที่ชัดเจน ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ 1. ด้านการปฏิบัติการ (1) จัดทำและปฏิบัติงานด้านเอกสารทางการเงินและบัญชีในระดับต้น เพื่อให้งานเป็นไปตามเป้าหมายที่กำหนด (2) รวบรวมรายละเอียดการจัดทำงบประมาณ เพื่อใช้ประกอบในการทำงบประมาณประจำปีของหน่วยงาน (3) ตรวจสอบและดูความถูกต้องของเอกสารสำคัญทางการเงิน เพื่อให้เกิดความถูกต้อง ในการปฏิบัติงาน 2. ด้านการบริการ (1) ให้คำแนะนำ ตอบปัญหา ชี้แจงเกี่ยวกับงานการเงินและบัญชี แก่เจ้าหน้าที่ระดับรองลงมา หน่วยงานราชการ เอกชน และประชาชนทั่วไป เพื่อถ่ายทอดความรู้ ความชำนาญแก่ผู้ที่สนใจ (2) ประสานงานในระดับฝ่ายหรือกลุ่ม กับหน่วยงานราชการ เอกชน หรือประชาชนทั่วไป เพื่อขอความช่วยเหลือและความร่วมมือในงานการเงินและบัญชี และแลกเปลี่ยนความรู้ความเชี่ยวชาญที่เป็นประโยชน์ต่อการทำงานของหน่วยงาน (3) ประสานงานในระดับฝ่ายหรือกลุ่ม กับหน่วยงานราชการ เอกชน หรือประชาชนทั่วไป เพื่อขอความช่วยเหลือและความร่วมมือในงาน และแลกเปลี่ยนความรู้ ความเชี่ยวชาญที่เป็นประโยชน์ต่อการทำงานของหน่วยงาน ทั้งนี้ การปฏิบัติงานในตำแหน่งดังกล่าวอาจมีภารกิจที่จะต้องอยู่ปฏิบัติงานนอกเหนือเวลาราชการเป็นเวลาบ่อยครั้ง โดยเฉพาะในช่วงจัดเตรียม วิเคราะห์ และจัดทำงบประมาณรายจ่ายประจำปี บริหารงบประมาณ ติดตามและประเมินผลการใช้จ่ายเงินงบประมาณ ตามที่ผู้บังคับบัญชามอบหมาย",
