    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/007.png",
    "คุณสมบัติเฉพาะ": "- ความรู้เกี่ยวกับหลักเกณฑ์กระทรวงการคลังว่าด้วยมาตรฐานและหลักเกณฑ์ปฏิบัติ การควบคุมภายในสำหรับหน่วยงานของรัฐ พ.ศ. 2561 และที่แก้ไขเพิ่มเติม - ความรู้เกี่ยวกับหลักเกณฑ์กระทรวงการคลังว่าด้วยมาตรฐานและหลักเกณฑ์ปฏิบัติ การตรวจสอบภายในสำหรับหน่วยงานของรัฐ พ.ศ. 2561 และที่แก้ไขเพิ่มเติม - ความรู้เกี่ยวกับการเงินการคลังภาครัฐ เช่น งบประมาณ การเงิน บัญชี พัสดุ เป็นต้น",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ที่ต้องใช้ความรู้ ความสามารถทางวิชาการในการทำงาน ปฏิบัติงานด้านตรวจสอบภายใน ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ 1. ด้านการปฏิบัติการ (1) รวบรวมและตรวจสอบความถูกต้องและความน่าเชื่อถือของข้อมูล ตัวเลข หลักฐานการทำสัญญา และเอกสารต่าง ๆ ทางด้านการเงิน การบัญชี เพื่อให้การตรวจสอบดำเนินไปอย่างถูกต้องและได้ผลตรงกับหลักฐานที่เกิดขึ้นจริง (2) ตรวจสอบการปฏิบัติงานเกี่ยวกับการบริหารงบประมาณ การเงิน พัสดุและทรัพย์สิน รวมทั้งการบริหารด้านอื่น ๆ ของส่วนราชการ เพื่อดูแลให้การใช้งบประมาณและทรัพยากรเป็นไปอย่างประหยัด มีประสิทธิภาพสูง และตรงตามวัตถุประสงค์ที่กำหนด (3) จัดทำรายงานการตรวจสอบรายเดือน เพื่อเสนอข้อตรวจพบและข้อเสนอแนะให้ผู้บังคับบัญชาหรือหน่วยงานต้นสังกัดรับทราบผลการดำเนินงาน 2. ด้านการวางแผน วางแผนการทำงานที่รับผิดชอบ ร่วมดำเนินการวางแผนการทำงานของหน่วยงาน หรือโครงการ เพื่อให้การดำเนินงานเป็นไปตามเป้าหมายและผลสัมฤทธิ์ที่กำหนด 3. ด้านการประสานงาน (1) ประสานการทำงานร่วมกันทั้งภายในและภายนอกทีมงานหรือหน่วยงาน เพื่อให้เกิดความร่วมมือและผลสัมฤทธิ์ตามที่กำหนด (2) ชี้แจงและให้รายละเอียดเกี่ยวกับข้อมูล ข้อเท็จจริง แก่บุคคลหรือหน่วยงานที่เกี่ยวข้อง เพื่อสร้างความเข้าใจหรือความร่วมมือในการดำเนินงานตามที่ได้รับมอบหมาย 4. ด้านการบริการ (1) ฝึกอบรม ให้คำปรึกษา เสนอแนะวิธีการปรับปรุงการปฏิบัติงานแก่หน่วยรับตรวจและเจ้าหน้าที่ระดับรองลงมา และตอบข้อซักถามและชี้แจงเรื่องต่าง ๆ เกี่ยวกับงานในหน้าที่ พร้อมทั้งช่วยแก้ปัญหาข้อขัดแย้งในหน่วยงานที่รับผิดชอบ เพื่อให้การปฏิบัติงานถูกต้องและมีประสิทธิภาพยิ่งขึ้น (2) ให้คำแนะนำ ตอบปัญหา และชี้แจง เกี่ยวกับงานตรวจสอบภายในที่ตนมีความรับผิดชอบในระดับเบื้องต้นแก่หน่วยงาน ราชการ เอกชน หรือประชาชนทั่วไป เพื่อให้ผู้ที่สนใจได้ทราบข้อมูลและความรู้ต่าง ๆ ที่เป็นประโยชน์",
