    "คุณสมบัติเฉพาะ": "- ความรู้เกี่ยวกับพระราชบัญญัติวินัยการเงินการคลังของรัฐ พ.ศ. 2561 - ความรู้เกี่ยวกับพระราชบัญญัติวิธีการงบประมาณ พ.ศ. 2561 - ความรู้เกี่ยวกับพระราชบัญญัติวิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539 และที่แก้ไขเพิ่มเติม - ความรู้เกี่ยวกับพระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ที่ต้องใช้ความรู้ ความสามารถทางวิชาการในการทำงาน ปฏิบัติงานด้านนิติการ ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ 1. ด้านการปฏิบัติการ (1) เสนอความเห็นแก่ผู้บังคับบัญชาในการตอบข้อหารือหรือวินิจฉัยปัญหากฎหมายเกี่ยวกับระเบียบของทางราชการที่มีผลกระทบต่อการดำเนินงานของหน่วยงาน เพื่อเป็นข้อมูลสนับสนุนการพิจารณาของผู้บังคับบัญชา (2) ศึกษา วิเคราะห์ และวิจัยเพื่อปรับปรุงกฎหมายและระเบียบเกี่ยวกับหน่วยงานที่รับผิดชอบ เพื่อให้ทันกับสถานการณ์และอำนวยความสะดวกในการทำงาน โดยพิจารณาถึงความเหมาะสมและเป็นธรรมต่อทุกฝ่าย (3) ศึกษาข้อมูล รวบรวม แสวงหาข้อเท็จจริงและข้อกฎหมาย เสนอความเห็นในการดำเนินการเรื่องใด ๆ ที่เกี่ยวกับวินัยข้าราชการ การร้องทุกข์ การพิทักษ์ระบบคุณธรรม รวมถึงการดำเนินการใด ๆ ตามกฎหมายปกครองที่เกี่ยวข้องกับการบริหารราชการ และการดำเนินคดีของหน่วยงานเพื่อใช้เป็นแนวทางในการปฏิบัติงาน และสามารถดำเนินการได้อย่างถูกต้อง 2. ด้านการวางแผน วางแผนการทำงานที่รับผิดชอบ ร่วมดำเนินการวางแผนการทำงานของหน่วยงาน หรือโครงการ เพื่อให้การดำเนินงานเป็นไปตามเป้าหมายและผลสัมฤทธิ์ที่กำหนด 3. ด้านการประสานงาน (1) ประสานการทำงานร่วมกันทั้งภายในและภายนอกทีมงานหรือหน่วยงาน เพื่อให้เกิดความร่วมมือและผลสัมฤทธิ์ตามที่กำหนด (2) ชี้แจงและให้รายละเอียดเกี่ยวกับข้อมูล ข้อเท็จจริง แก่บุคคลหรือหน่วยงานที่เกี่ยวข้อง เพื่อสร้างความเข้าใจหรือความร่วมมือในการดำเนินงานตามที่ได้รับมอบหมาย 4. ด้านการบริการ ให้คำปรึกษาแนะนำด้านกฎหมายแก่บุคคลหรือหน่วยงานที่เกี่ยวข้อง เพื่อสร้างความเข้าใจ ในข้อกฎหมายที่เป็นปัญหา และให้ความรู้ถึงข้อกฎหมายที่เกี่ยวข้องและเป็นประโยชน์กับการดำเนินงานของบุคคลหรือหน่วยงานดังกล่าว",
