    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้นที่ต้องใช้ความรู้ ความสามารถทางวิชาการในการทำงานปฏิบัติงานด้านการบริหารจัดการ ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติ ดังนี้ 1) จัดทำแผนการจัดซื้อจัดจ้างประจำปี แผนปฏิบัติการ และรายงานผลการดำเนินการตามแผนฯ 2) จัดทำสัญญา ข้อตกลง และเอกสารต่าง ๆ ในการจัดซื้อจัดจ้าง 3) ควบคุมดูแลการใช้ประโยชน์ บำรุงรักษา และซ่อมแซมครุภัณฑ์ อาคารสถานที่และยานพาหนะ 4) จัดทำทะเบียนรายละเอียดพัสดุของสำนักงาน (วัสดุ และครุภัณฑ์) ตรวจสอบพัสดุประจำปี และจำหน่ายพัสดุ 5) กำกับ ดูแล และดำเนินมาตรการประหยัดพลังงาน รวมทั้งติดตามประเมินผลการดำเนินการ 6) บริหารจัดการการเบิกจ่ายวัสดุสำนักงาน และการยืม - คืน ครุภัณฑ์สำนักงาน 7) ให้คำแนะนำ ชี้แจงปัญหา/ข้อสงสัยเกี่ยวกับการจัดซื้อจัดจ้างและการบริหารพัสดุ 8) บันทึกข้อมูลเกี่ยวกับการจัดซื้อ/จ้าง/เช่า การจ้างที่ปรึกษา และอื่นๆ ที่เกี่ยวข้องในระบบจัดซื้อจัดจ้างภาครัฐด้วยอิเล็กทรอนิกส์ (Electronic Government Procurement : e - GP) และระบบบริหารการเงินการคลังภาครัฐแบบอิเล็กทรอนิกส์ใหม่ (New GFMIS Thai) ตามที่กรมบัญชีกลางกำหนด 9) จัดทำบันทึกขออนุมัติเบิกจ่ายเงินสำหรับการจัดซื้อ/จ้าง/เช่า 10) ปฏิบัติหน้าที่อื่นที่เกี่ยวข้องหรือที่ได้รับมอบหมาย",
