    "รายละเอียดงาน": "ช่วยปฏิบัติงานด้านประมง งานศึกษาทดลอง วิเคราะห์ และวิจัยทางวิชาการประมง เพื่อพัฒนาองค์ความรู้ที่เป็นประโยชน์ งานสำรวจ ศึกษา ทดลอง วิเคราะห์ และวิจัยทางวิชาการเกี่ยวกับทรัพยากรสัตว์น้ำและสิ่งแวดล้อมในระบบนิเวศทางทะเลและชายฝั่ง เพื่อส่งเสริมและพัฒนางานด้านระบบนิเวศทางทะเลและชายฝั่ง ดำเนินการตามแผนการอนุรักษ์และฟื้นฟูทรัพยากรสัตว์น้ำและสิ่งแวดล้อม เพื่อการใช้ทรัพยากรอย่างยั่งยืน จัดทำทะเบียนจับสัตว์น้ำ และทะเบียนอื่น ๆ เกี่ยวกับการประมง เพื่อควบคุมให้การดำเนินการต่าง ๆ เป็นไปตามประกาศและกฎระเบียบของทางราชการ รวบรวมรายละเอียดสถิติข้อมูลและดำเนินการต่าง ๆ เพื่อการวิเคราะห์วิจัยทางการประมง และจัดทำรายงานการดำเนินงานเกี่ยวกับการประกอบการประมงเพื่อประกอบการวางแผนงานและนโยบายของหน่วยงาน ดูแลการประกอบการประมงของผู้ประกอบอาชีพการเพาะเลี้ยงสัตว์น้ำและชาวประมง เพื่อให้เป็นไปตามที่กฎหมายกำหนด ปลอดภัย เป็นไปตามมาตรฐานและไม่ทำลายสมดุลของสิ่งแวดล้อม และปฏิบัติงานอื่น ๆ ที่เกี่ยวข้องตามที่ได้รับมอบหมาย",
