    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/10100.png",
    "คุณสมบัติเฉพาะ": "1. สำเร็จการศึกษาวุฒิการศึกษาระดับประกาศนียบัตรวิชาชีพขั้นสูง (ปวส.) ประเภทวิชาพาณิชยกรรม/บริหารธุรกิจที่เกี่ยวข้องเหมาะสมกับลักษณะงานที่ปฏิบัติ 2. สำเร็จการศึกษาวุฒิการศึกษาระระดับประกาศนียบัตรวิชาชีพขั้นสูง (ปวช.) ประเภทวิชาพาณิชยกรรม/บริหารธุรกิจที่เกี่ยวข้องเหมาะสมกับลักษณะงานที่ปฏิบัติ",
    "รายละเอียดงาน": "ปฏิบัติงานด้านธุรการ งานสารบรรณ งานบริการทั่วไป และงานการเงิน เช่น การรับ-ส่งหนังสือราชการของหน่วยงาน การคัดแยกหนังสือราชการส่งไปยังงานต่าง ๆ รวมทั้งระบบงานสารบรรณอิเล็กทรอนิกส์ การตอบหนังสือราชการ การตรวจสอบเอกสารทางการเงิน การบันทึกข้อมูลการเบิก – จ่าย ติดต่อประสานงานกับบุคคลภายในหน่วยงาน หรือหน่วยงานที่เกี่ยวข้อง และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย",
