    "ลิงก์": "https://mwi.anamai.moph.go.th/th/moph-job",
    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10582.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/168.png",
    "คุณสมบัติเฉพาะ": "เป็นผู้ได้รับปริญญาตรีหรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกัน ในสาขาวิชาศึกษาศาสตร์ ทางการศึกษาปฐมวัย ทางปฐมวัยศึกษา ทางการพัฒนาเด็กปฐมวัย ทางการศึกษาพิเศษ ทางการศึกษาพิเศษ และการศึกษาปฐมวัย หรือ ปริญญาครุศาสตรบัณฑิต สาขาวิชาศึกษาปฐมวัย ปริญญาศึกษาศาสตรบัณฑิต สาขาวิชาการศึกษาปฐมวัย ปริญญาการศึกษาบัณฑิต สาขาวิชาการศึกษาปฐมวัย และปริญญาศิลปศาสตร บัณฑิต สาขาการพัฒนาเด็กปฐมวัย",
    "รายละเอียดงาน": "ปฏิบัติงานทางด้านวิชาการศึกษา ซึ่งมีลักษณะงานที่ปฏิบัติเกี่ยวกับการศึกษา ดังนี้ ๑) ศึกษา วิเคราะห์ข้อมูลเกี่ยวกับการศึกษา เพื่อเป็นข้อมูลประกอบการพัฒนางานด้านวิชาการศึกษาและ ที่เกี่ยวข้องกับเด็กปฐมวัย ๒) ศึกษา วิเคราะห์ วิจัยเบื้องต้น เพื่อประกอบการจัดทำข้อเสนอนโยบาย แผน มาตรฐานการศึกษา หลักสูตรแบบเรียน ตำรา สื่อการเรียนการสอน สื่อการศึกษา การผลิตและพัฒนาสื่อนวัตกรรมและ เทคโนโลยี การส่งเสริมสนับสนุนการจัดการศึกษาเด็กปฐมวัย ๓) จัดทำแผนงาน/โครงการต่างๆ เพื่อส่งเสริมสนับสนุนการจัดการศึกษาเด็กปฐมวัย ๔) ดำเนินการเกี่ยวกับงานทะเบียนและเอกสารด้านการศึกษา รวมทั้งปรับปรุงให้ทันสมัย เพื่อเป็นหลักฐาน อ้างอิงและให้การส่งเสริมสนับสนุนการจัดการศึกษาเด็กปฐมวัย ๕) ส่งเสริมสนับสนุนการจัดการศึกษา เพื่อให้การจัดการศึกษาที่มีคุณภาพและมาตรฐานศูนย์เด็กเล็กแห่งชาติ ๖) ติดตาม ประเมินผลการดำเนินงาน กิจกรรมและสรุปผลด้านการศึกษา วิเคราะห์ วิจัย เพื่อพัฒนางาน ด้านการศึกษาเด็กปฐมวัย ๗) จัดบริการส่งเสริมการศึกษา เช่น จัดนิทรรศการ กิจกรรม พิพิธภัณฑ์ทางการศึกษาและแหล่งเรียนรู้ เพื่อให้การบริการความรู้และบริการทางด้านการศึกษาและวิชาชีพแก่ประชาชนอย่างทั่วถึง ๘) ปฏิบัติงานอื่นๆ ตามที่ได้รับมอบหมาย",
