    "รายละเอียดงาน": "ปฏิบัติงานเชิงกลยุทธ์ด้านการตลาดดิจิทัลและการประชาสัมพันธ์เชิงรุก ตลอดจนบริหารจัดการคลังสื่อและอุปกรณ์สตูดิโอของคณะฯ และงานอื่น ๆ ตามที่ได้รับมอบหมาย โดยมีหน้าที่ความรับผิดชอบหลักดังนี้ ด้านการตลาดดิจิทัล วางแผนการตลาดเพื่อดึงดูดผู้สมัครเรียน, บริหารจัดการโฆษณาออนไลน์ (Facebook/Google Ads/TikTok), ดูแลระบบ SEO/SEM และใช้ระบบ CRM/Retargeting เพื่อติดตามกลุ่มเป้าหมาย ด้านการผลิตสื่อ ผลิตคอนเทนต์วิดีโอสั้น ภาพอินโฟกราฟิก และสัมภาษณ์พิเศษคณาจารย์ ศิษย์เก่า และนักศึกษา เพื่อสร้างภาพลักษณ์ทีดี่ของคณะบริหารธุรกิจ ด้านประชาสัมพันธ์และการจัดกิจกรรม ดำเนินการสื่อสารกับสื่อมวลชน ควบคุมมาตรฐานอัตลักษณ์องค์กร (CI) ของคณะฯ ประสานงานจัดกิจกรรมหน่วยงาน เช่น งาน Open House และการออกบูธแนะแนวการศึกษาร่วมกับส่วนงานอื่นๆ ของคณะฯ และของสถาบันฯ ด้านการบริหารคลังสื่อและระบบสตูดิโอ บริหารจัดการจัดเก็บคลังสื่อดิจิทัล (ภาพถ่าย, วิดีโอ, กราฟิก) บนระบบ Cloud และดูแล รักษา อุปกรณ์ถ่ายทำและระบบสตูดิโอของคณะฯ ให้พร้อมใช้งานอยู่เสมอ",
