    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10596.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/162.png",
    "คุณสมบัติเฉพาะ": "1. พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 และระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 2. พระราชบัญญัติวิธีการงบประมาณ พ.ศ. 2561 3. พระราชบัญญัติวินัยการเงินการคลังของรัฐ พ.ศ. 2561 4. พระราชบัญญัติการปฏิบัติราชการทางอิเล็กทรอนิกส์ พ.ศ. 2565 5. พระราชกฤษฎีกาว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546 และที่แก้ไขเพิ่มเติม 6. ความรู้เกี่ยวกับยุทธศาสตร์ชาติ 20 ปี และแผนพัฒนาเศรษฐกิจและสังคมแห่งชาติ ฉบับที่ 13 7. ความรู้เกี่ยวกับสถิติเบื้องต้น การวิเคราะห์ข้อมูล และการคิดเชิงวิพากษ์ 8. ความรู้เกี่ยวกับการจัดทำโครงการ การจัดทำตัวชี้วัด (KPI) และการพัฒนาคุณภาพการบริหารจัดการภาครัฐ (PMQA) 9. ความรู้เกี่ยวกับวิสัยทัศน์ พันธกิจ ค่านิยม โครงสร้างกรม และหน่วยงานในสังกัดกรมการแพทย์",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ที่ต้องใช้ความรู้ ความสามารถทางวิชาการในการทำงาน ปฏิบัติงานด้านวิเคราะห์นโยบายและแผน ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ 1. ด้านการปฏิบัติการ (1) รวบรวม วิเคราะห์ และประมวลนโยบายของรัฐบาลและสถานการณ์เศรษฐกิจ การเมือง และสังคม ทั้งในและต่างประเทศ เพื่อนำมาสรุปเสนอประกอบการกำหนดนโยบายและเป้าหมายของส่วนราชการ หรือนโยบาย แผนงาน และโครงการทางเศรษฐกิจ สังคม การเมือง การบริหาร หรือความมั่นคง (2) รวบรวมข้อมูล และศึกษาวิเคราะห์เบื้องต้น เกี่ยวกับภารกิจหลักและแผนกลยุทธ์ของส่วนราชการ หรือทิศทางการพัฒนาเศรษฐกิจ สังคม การเมือง เพื่อวางแผนกำหนดแผนการปฏิบัติงาน หรือโครงการ ให้สามารถบรรลุภารกิจที่กำหนดไว้ (3) วิเคราะห์นโยบายของส่วนราชการ หรือนโยบาย แผนงาน และโครงการทางเศรษฐกิจ สังคม การเมือง การบริหาร หรือความมั่นคง และเสนอข้อคิดเห็น เพื่อช่วยจัดทำแผนการปฏิบัติงาน แผนงาน โครงการ หรือ กิจกรรมได้ตามวัตถุประสงค์ที่ตั้งไว้ (4) สำรวจ รวบรวม และประมวลผลข้อมูลการดำเนินงานตามนโยบายรัฐบาลและประเด็นปัญหา ทางเศรษฐกิจ การเมือง และสังคม ทั้งในและต่างประเทศ เพื่อเป็นข้อมูลสำหรับการจัดทำแผนงาน หรือกำหนดยุทธศาสตร์ (5) ศึกษาวิเคราะห์ความสัมพันธ์ระหว่างยุทธศาสตร์และนโยบายของรัฐบาล เพื่อประกอบการเสนอแนะแนวทางการประสานผลักดันยุทธศาสตร์และนโยบาย ตลอดจนการติดตาม ประเมินผลให้สอดคล้องไปในแนวทางเดียวกัน 2. ด้านการวางแผน วางแผนการทำงานที่รับผิดชอบ ร่วมดำเนินการวางแผนการทำงานของหน่วยงานหรือโครงการ เพื่อให้การดำเนินงานเป็นไปตามเป้าหมายและผลสัมฤทธิ์ที่กำหนด 3. ด้านการประสานงาน (1) ประสานการทำงานร่วมกันทั้งภายในและภายนอกทีมงานหรือหน่วยงาน เพื่อให้เกิดความร่วมมือและผลสัมฤทธิ์ตามที่กำหนด (2) ชี้แจงและให้รายละเอียดเกี่ยวกับข้อมูล ข้อเท็จจริง แก่บุคคลหรือหน่วยงานที่เกี่ยวข้อง เพื่อสร้างความเข้าใจหรือความร่วมมือในการดำเนินงานตามที่ได้รับมอบหมาย 4. ด้านการบริการ (1) รวบรวมข้อมูล เพื่อเผยแพร่และถ่ายทอดองค์ความรู้ที่เกี่ยวกับการจัดทำแผนงาน โครงการ (2) ให้คำปรึกษา แนะนำ ตอบปัญหา และชี้แจงเรื่องต่างๆ เกี่ยวกับงานนโยบายและแผน เพื่อแก้ปัญหาในการปฏิบัติงาน",
