    "ระดับการศึกษา": "ป.ตรี | ได้รับปริญญาตรีหรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกัน ในสาขาวิชาแพทยศาสตร์ สาขาวิชาสัตวแพทยศาสตร์ สาขาวิชาวิทยาศาสตร์การแพทย์ สาขาวิชาวิทยาศาสตร์ชีวภาพ สาขาวิชาวิทยาศาสตร์กายภาพ สาขาวิชาวิทยาศาสตร์ประยุกต์ สาขาวิชาเกษตรศาสตร์ สาขาวิชาเภสัชศาสตร์ สาขาวิชาเทคนิคการแพทย์ สาขาวิชาสาธารณสุขศาสตร์ สาขาวิชาวิทยาการสิ่งแวดล้อมและทรัพยากรธรรมชาติ สาขาวิชาเทคโนโลยีชีวภาพ สาขาวิชาคณิตศาสตร์และสถิติ สาขาวิชาศึกษาศาสตร์ ทางชีววิทยา สาขาวิชาวิศวกรรมศาสตร์ ทางวิศวกรรมสิ่งแวดล้อม หรือทางวิศวกรรมสุขาภิบาล",
