    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10596.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/162.png",
    "คุณสมบัติเฉพาะ": "1. พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 2. พระราชบัญญัติการปฏิบัติราชการทางอิเล็กทรอนิกส์ พ.ศ. 2565 3. ความรู้เกี่ยวกับข้อกำหนดด้านความปลอดภัยในห้องปฏิบัติการ 4. ความรู้ทั่วไปทางวิทยาศาสตร์การแพทย์ และสถิติเบื้องต้น 5. การวางแผน และการบริหารจัดการงานบริการทางวิชาการ 6. ภาษาอังกฤษเบื้องต้นในการปฏิบัติงานวิทยาศาสตร์การแพทย์ 7. ความรู้เกี่ยวกับวิสัยทัศน์ พันธกิจ ค่านิยม โครงสร้างกรม และหน่วยงานในสังกัดกรมการแพทย์",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ที่ต้องใช้ความรู้ ความสามารถทางวิชาการในการทำงาน ปฏิบัติงานด้านวิทยาศาสตร์การแพทย์ ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ 1. ด้านการปฏิบัติการ (1) ตรวจ วิเคราะห์ตัวอย่างทางการแพทย์และสาธารณสุขที่ใช้วิธีการ เครื่องมือ เทคโนโลยี พื้นฐาน โดยการประกันคุณภาพให้เป็นไปตามมาตรฐานสากล การบังคับใช้กฎหมายด้านสาธารณสุข และเป็นข้อมูลในการป้องกัน วินิจฉัย รักษา พยากรณ์โรค สอบสวนและเฝ้าระวังการระบาดของโรค การประเมินภาวะสุขภาพ คัดกรองสุขภาพ หรือผลกระทบต่อสิ่งแวดล้อมต่อสุขภาพ ตลอดจนประกอบการพิจารณาทางอรรถคดี เพื่อสนับสนุนการคุ้มครองผู้บริโภคและสุขภาพของประชาชน (2) ร่วมวิจัยทางด้านการแพทย์และสาธารณสุขให้ได้องค์ความรู้ นวัตกรรม เทคโนโลยี ผลิตภัณฑ์ทางด้านสุขภาพและวิทยาศาสตร์การแพทย์ การประเมินความเสี่ยง เตือนภัยสุขภาพ การตั้งเกณฑ์ หรือปรับเปลี่ยนค่ามาตรฐานต่าง ๆ ของประเทศ และการป้องกัน วินิจฉัย รักษา พยากรณ์โรค สอบสวนโรค เพื่อความปลอดภัยในชีวิตและสนับสนุนสุขภาวะของประชาชน (3) ร่วมดำเนินการประกันคุณภาพห้องปฏิบัติการทางการแพทย์และสาธารณสุข โดยพัฒนา ประเมินคุณภาพการตรวจวิเคราะห์ และรับรองความสามารถห้องปฏิบัติการ ตามมาตรฐานสากล เพื่อสนับสนุน คุ้มครองสุขภาวะของประชาชน 2. ด้านการวางแผน วางแผนการทำงานที่รับผิดชอบ ร่วมดำเนินการวางแผนการทำงานของหน่วยงานหรือโครงการ เพื่อให้การดำเนินงานเป็นไปตามเป้าหมายและผลสัมฤทธิ์ที่กำหนด 3. ด้านการประสานงาน (1) ประสานการทำงานร่วมกันทั้งภายในและภายนอกทีมงานหรือหน่วยงาน เพื่อให้เกิดความร่วมมือและผลสัมฤทธิ์ตามที่กำหนด (2) ชี้แจงและให้รายละเอียดเกี่ยวกับข้อมูล ข้อเท็จจริง แก่บุคคลหรือหน่วยงานที่เกี่ยวข้อง เพื่อสร้างความเข้าใจหรือความร่วมมือในการดำเนินงานตามที่ได้รับมอบหมาย 4. ด้านการบริการ (1) สนับสนุนการถ่ายทอดความรู้ทางวิชาการหรือเทคโนโลยีแก่บุคคลภายในหน่วยงาน เพื่อให้มีความรู้ และให้สามารถดำเนินงานให้มีประสิทธิภาพ (2) ให้บริการทางวิชาการ เช่น การจัดทำเอกสาร ตำรา คู่มือ เอกสารสื่อเผยแพร่ ในรูปแบบต่าง ๆ เพื่อการเรียนรู้และความเข้าใจในระดับต่าง ๆ ในด้านวิทยาศาสตร์การแพทย์ (3) ร่วมปฏิบัติการในการพัฒนาศักยภาพของบุคลากร และองค์กร เพื่อให้เป็นบุคลากรที่มีความชำนาญและปฏิบัติงานได้อย่างมีประสิทธิภาพ (4) นิเทศงานด้านวิทยาศาสตร์การแพทย์หรือด้านอื่นให้แก่ผู้เกี่ยวข้อง เพื่อให้สามารถปฏิบัติงาน ได้อย่างถูกต้องและมีประสิทธิภาพ",
