    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/162.png",
    "คุณสมบัติเฉพาะ": "1. ความรู้เกี่ยวกับหลักโภชนาการทั่วไป 2. ความรู้เกี่ยวกับนมและอาหารทางการแพทย์สำหรับผู้ป่วยเด็ก 3. ความรู้เกี่ยวกับหลักสุขาภิบาลอาหาร มาตรฐานอาหารปลอดภัย และมาตรฐานคุณภาพอาหารในโรงพยาบาล 4. ความรู้เกี่ยวกับการให้คำปรึกษา แนะนำ ด้านโภชนาการ 5. ความรู้เกี่ยวกับ 5 องค์ความรู้ของสมาคมนักกำหนดอาหารแห่งประเทศไทย (CDT) 6. ความรู้เกี่ยวกับวิสัยทัศน์ พันธกิจ ค่านิยม โครงสร้างกรม และหน่วยงานในสังกัดกรมการแพทย์",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ซึ่งไม่จำเป็นต้องใช้ผู้สำเร็จการศึกษาระดับปริญญา ปฏิบัติงานด้านโภชนาการ ตามแนวทาง แบบอย่าง ขั้นตอน และวิธีการที่ชัดเจน ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ 1. ด้านการปฏิบัติการ (1) ให้บริการอาหารตามหลักโภชนาการ โภชนบำบัด เพื่อให้ผู้ใช้บริการได้รับพลังงาน สารอาหารครบถ้วนและปลอดภัย (2) จัดเตรียม ดูแล บำรุงรักษาเครื่องมือ วัสดุ อุปกรณ์ เพื่อให้อยู่ในสภาพพร้อมใช้งาน และเป็นไปตามมาตรฐาน (3) เก็บรวบรวมข้อมูล เพื่อจัดทำรายงาน และนำเสนอเจ้าหน้าที่ระดับสูงขึ้นไป 2. ด้านการบริการ (1) ให้คำแนะนำด้านอาหารตามหลักโภชนาการ โภชนบำบัด แก่ผู้ใช้บริการ เพื่อให้มีความรู้ สามารถนำไปปฏิบัติในชีวิตประจำวันได้ (2) ประสานงานการทำงานร่วมกับผู้เกี่ยวข้อง เพื่อให้การดำเนินงานเป็นไปอย่างราบรื่น และมีประสิทธิภาพ",
