    "คุณสมบัติเฉพาะ": "1. พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 และระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 2. ความรู้เกี่ยวกับงานช่างพื้นฐาน 3. ความรู้เกี่ยวกับการดูแล และบำรุงรักษาระบบสาธารณูปโภค เครื่องจักร เครื่องมือ อุปกรณ์ต่างๆ วัสดุและครุภัณฑ์อื่นๆ 4. ความรู้เกี่ยวกับความปลอดภัย อาชีวอนามัย และสิ่งแวดล้อมในการปฏิบัติงานช่าง 5. ความรู้เกี่ยวกับการควบคุมงานก่อสร้าง งานปรับปรุง ซ่อมแซม และตรวจการจ้าง 6. ความรู้เกี่ยวกับวิสัยทัศน์ พันธกิจ ค่านิยม โครงสร้างกรม และหน่วยงานในสังกัดกรมการแพทย์",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ซึ่งไม่จำเป็นต้องใช้ผู้สำเร็จการศึกษาระดับปริญญา ปฏิบัติงานด้านช่างเทคนิค ตามแนวทาง แบบอย่าง ขั้นตอน และวิธีการที่ชัดเจน ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ 1. ด้านการปฏิบัติการ (1) ดูแล ควบคุม ตรวจซ่อมและบำรุงรักษา ระบบสาธารณูปโภค เครื่องจักร เครื่องยนต์ เครื่องมือ อุปกรณ์ต่าง ๆ วัสดุและครุภัณฑ์อื่น ๆ ในความรับผิดชอบ เพื่อให้เกิดความปลอดภัยและพร้อมในการใช้งาน (2) ซ่อม สร้าง ผลิต ประกอบ ดัดแปลง เขียนหรือออกแบบ ติดตั้ง เครื่องจักร เครื่องยนต์ เครื่องมือ อุปกรณ์ต่างๆ รวมทั้งการทดลองใช้เครื่องจักร เครื่องกล และสิ่งก่อสร้าง เพื่อให้เป็นไปตามหลักวิชาและมาตรฐานงานช่าง และให้เกิดความปลอดภัย 2. ด้านการบริการ (1) ให้คำปรึกษา แนะนำ จัดทำข้อมูล ถ่ายทอดความรู้ทั้งในเชิงทักษะเฉพาะด้านและทักษะทั่วไปให้แก่บุคลากรภายในหน่วยงานที่รับผิดชอบ หน่วยงานราชการ เอกชน และประชาชน เพื่อให้มีความรู้ความสามารถและมีทักษะเหมาะสมแก่การปฏิบัติงานในหน้าที่ (2) ติดต่อประสานกับหน่วยงานหรือเจ้าหน้าที่ที่เกี่ยวข้อง เพื่อให้การดำเนินงานเป็นไปอย่างมีประสิทธิภาพ และปฏิบัติหน้าที่อื่นที่เกี่ยวข้องตามที่ได้รับมอบหมาย",
