    "คุณสมบัติเฉพาะ": "1. ความรู้เกี่ยวกับหลักการอาชีวบำบัดเบื้องต้น 2. ความรู้เกี่ยวกับจิตวิทยาการฟื้นฟูสมรรถภาพผู้ป่วย 3. ความรู้เกี่ยวกับการส่งเสริมศักยภาพ ฟื้นฟู และการจัดการดูแลผู้ป่วย 4. ความรู้เกี่ยวกับการดูแลรักษาเครื่องมืออุปกรณ์ และการจัดการสิ่งแวดล้อมเพื่อความปลอดภัยในการปฏิบัติงาน 5. ความรู้เกี่ยวกับเกษตรและคหกรรม (งานอาหาร และงานผ้าเพื่อการฝึกอาชีพ) 6. ความรู้เกี่ยวกับวิสัยทัศน์ พันธกิจ ค่านิยม โครงสร้างกรม และหน่วยงานในสังกัดกรมการแพทย์",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ซึ่งไม่จำเป็นต้องใช้ผู้สำเร็จการศึกษาระดับปริญญา ปฏิบัติงานด้านอาชีวบำบัด ตามแนวทาง แบบอย่าง ขั้นตอน และวิธีการที่ชัดเจน ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ 1. ด้านการปฏิบัติการ (1) ปฏิบัติงานอาชีวบำบัดเบื้องต้น เพื่อให้ผู้ป่วยได้รับการบริการที่ถูกต้องเหมาะสม โดยใช้ความรู้ ทักษะ ประสบการณ์ และความชำนาญ เพื่อมุ่งเน้นให้ผู้ป่วยได้เรียนรู้การประกอบอาชีพ ผ่านการฝึกปฏิบัติ ให้เกิดทักษะในงานอาหารและโภชนาการ หรือการตัดเย็บวัสดุจากผ้า (2) ควบคุม เฝ้าระวัง และรายงานผลการให้บริการงานด้านอาชีวบำบัดของผู้ป่วยที่ไม่ยุ่งยากซับซ้อน เพื่อดำเนินการบำบัดและฟื้นฟูผู้ป่วย (3) จัดเตรียม ดูแล บำรุงรักษา ซ่อมแซ่ม อุปกรณ์และเครื่องมือเครื่องใช้ในการปฏิบัติงาน เพื่ออำนวยความสะดวกและพร้อมให้บริการผู้ป่วยได้ (4) จัดสิ่งแวดล้อมให้เหมาะสมกับสภาพในการปฏิบัติงาน เพื่อพัฒนาสภาพจิตใจและความสะดวก ปลอดภัยของผู้ป่วย (5) ร่วมพัฒนาศักยภาพของบุคลากรในองค์กร เพื่อให้เป็นบุคลากรที่มีความชำนาญ และปฏิบัติงานได้อย่างมีประสิทธิภาพ 2. ด้านการบริการ (1) ประชาสัมพันธ์ แนะนำความรู้ในงานด้านอาชีวบำบัดเบื้องต้นแก่ผู้ป่วย ญาติ และเจ้าหน้าที่ เพื่อให้มีความรู้ ความเข้าใจที่ถูกต้อง (2) ติดต่อประสานงานภายในกลุ่มงานเดียวกัน เพื่อให้สามารถบริการผู้ป่วยได้อย่างมีประสิทธิภาพ",
