    "ระดับการศึกษา": "ปวส., อนุปริญญา | ได้รับประกาศนียบัตรวิชาชีพชั้นสูงหรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกัน ในทุกสาขาวิชา หรือ ได้รับอนุปริญญาหลักสูตร 3 ปี หรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกัน ในทุกสาขาวิชา ",
