    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10596.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/162.png",
    "คุณสมบัติเฉพาะ": "1. พระราชบัญญัติข้อมูลข่าวสารของราชการ พ.ศ. 2540 และที่แก้ไขเพิ่มเติม 2. พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 และระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 3. พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 4. พระราชบัญญัติการปฏิบัติราชการทางอิเล็กทรอนิกส์ พ.ศ. 2565 5. ระเบียบสำนักนายกรัฐมนตรีว่าด้วยงานสารบรรณ พ.ศ. 2526 และที่แก้ไขเพิ่มเติม 6. ระเบียบว่าด้วยการรักษาความลับของทางราชการ พ.ศ. 2544 และที่แก้ไขเพิ่มเติม 7. ความรู้เกี่ยวกับการใช้งานคอมพิวเตอร์ โปรแกรม Microsoft Office และโปรแกรมประชุมออนไลน์ 8. ความรู้เกี่ยวกับวิสัยทัศน์ พันธกิจ ค่านิยม โครงสร้างกรม และหน่วยงานในสังกัดกรมการแพทย์",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ซึ่งไม่จำเป็นต้องใช้ผู้สำเร็จการศึกษาระดับปริญญา ปฏิบัติงานด้านธุรการ ตามแนวทาง แบบอย่าง ขั้นตอน และวิธีการที่ชัดเจน ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ 1. ด้านการปฏิบัติการ (1) ปฏิบัติงานธุรการ งานสารบรรณ งานบริการทั่วไป เช่น การรับส่ง ลงทะเบียน ร่างหนังสือโต้ตอบ จัดเตรียมการประชุม การบันทึกข้อมูล เพื่อสนับสนุนให้งานต่าง ๆ ดำเนินไปได้โดยสะดวกราบรื่น และมีหลักฐานตรวจสอบได้ (2) รวบรวมข้อมูล จัดเก็บข้อมูลสถิติ เอกสาร หลักฐานหนังสือ ตามระเบียบวิธีปฏิบัติ เพื่อสะดวกต่อการค้นหา และเป็นหลักฐานทางราชการ (3) ดำเนินการเกี่ยวกับพัสดุ ครุภัณฑ์ของสำนักงาน เพื่อให้มีอุปกรณ์ที่มีคุณภาพไว้ใช้งาน และอยู่ในสภาพพร้อมใช้งาน (4) รวบรวมรายงานผลการปฏิบัติงานและข้อมูลต่าง ๆ นำเสนอต่อผู้บังคับบัญชา เพื่อนำไปใช้เสนอแนะและปรับปรุงการปฏิบัติงานต่อไป 2. ด้านการบริการ (1) ติดต่อประสานงานกับบุคคลภายในหน่วยงานเดียวกันหรือหน่วยงานที่เกี่ยวข้อง เพื่อให้การปฏิบัติงานเป็นไปด้วยความราบรื่น (2) ให้บริการข้อมูลแก่ผู้มาติดต่อราชการ เพื่อให้ได้รับข้อมูลที่จะนำไปใช้ประโยชน์ได้ต่อไป (3) ผลิตเอกสารต่าง ๆ เพื่อสนับสนุนการปฏิบัติงานตามภารกิจของหน่วยงาน และปฏิบัติหน้าที่อื่น ที่เกี่ยวข้องตามที่ได้รับมอบหมาย",
