    "คุณสมบัติเฉพาะ": "1. พระราชบัญญัติการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 และระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ พ.ศ. 2560 2. ความรู้เกี่ยวกับระบบการจัดซื้อจัดจ้างภาครัฐด้วยอิเล็กทรอนิกส์ (e-GP) และการบริหารจัดการคลังพัสดุ และครุภัณฑ์ 3. พระราชบัญญัติวินัยการเงินการคลังของรัฐ พ.ศ. 2561 และความรู้เบื้องต้นเกี่ยวกับวิธีการงบประมาณ 4. ความรู้เกี่ยวกับระเบียบว่าด้วยการบริหารงบประมาณ พ.ศ. 2562 5. พระราชบัญญัติการปฏิบัติราชการทางอิเล็กทรอนิกส์ พ.ศ. 2565 6. ความรู้เกี่ยวกับจรรยาบรรณของผู้ปฏิบัติงานด้านพัสดุ 7. ความรู้เกี่ยวกับวิสัยทัศน์ พันธกิจ ค่านิยม โครงสร้างกรม และหน่วยงานในสังกัดกรมการแพทย์",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ซึ่งไม่จำเป็นต้องใช้ผู้สำเร็จการศึกษาระดับปริญญา ปฏิบัติงานด้านพัสดุ ตามแนวทาง แบบอย่าง ขั้นตอน และวิธีการที่ชัดเจน ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ 1. ด้านการปฏิบัติการ (1) ปฏิบัติงานขั้นต้นเกี่ยวกับงานพัสดุในการจัดหา จัดซื้อ ว่าจ้าง การเก็บรักษา นำส่ง การซ่อมแซม และบำรุงรักษาพัสดุ ครุภัณฑ์ อุปกรณ์เครื่องมือเครื่องใช้ต่าง ๆ เพื่อให้อยู่ในสภาพดี พร้อมต่อการใช้งาน (2) ทำทะเบียนการเบิกจ่ายพัสดุ การเก็บรักษาใบสำคัญหลักฐานและเอกสารเกี่ยวกับพัสดุ เพื่อรวบรวมไว้เป็นข้อมูลในการดำเนินงาน (3) ร่างและตรวจสัญญาซื้อ สัญญาจ้าง หนังสือโต้ตอบ บันทึกย่อเรื่องเกี่ยวกับงานพัสดุ เพื่อเป็นหลักฐานในการดำเนินงาน (4) รายงาน สรุปความเห็นเกี่ยวกับงานพัสดุ เพื่อจัดทำรายงาน และนำเสนอผู้บังคับบัญชาในหน่วยงาน (5) ศึกษาและเสนอความเห็นเกี่ยวกับระเบียบงานพัสดุ เพื่อร่วมพัฒนาให้ระเบียบการปฏิบัติงาน มีประสิทธิภาพ และรวดเร็วยิ่งขึ้น (6) ชี้แจงรายละเอียดข้อเท็จจริงเกี่ยวกับงานพัสดุให้การปฏิบัติงานมีความโปร่งใส ตรวจสอบได้ 2. ด้านการบริการ (1) ให้คำแนะนำเกี่ยวกับระเบียบ และวิธีการปฏิบัติงานที่อยู่ในความรับผิดชอบแก่ผู้ร่วมงาน หรือหน่วยงานที่เกี่ยวข้อง เพื่อความเข้าใจอันดีในการปฏิบัติงาน และให้การดำเนินงานสำเร็จลุล่วง (2) ประสานงานกับบุคคลภายในหน่วยงานเดียวกัน ต่างหน่วยงาน หรือประชาชนทั่วไป เพื่อให้บริการ หรือขอความช่วยเหลือในด้านที่ตนรับผิดชอบ",
