    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/162.png",
    "คุณสมบัติเฉพาะ": "1. พระราชบัญญัติประกันสังคม พ.ศ. 2533 และที่แก้ไขเพิ่มเติม 2. พระราชบัญญัติประกันสุขภาพแห่งชาติ พ.ศ. 2545 3. ระเบียบกระทรวงสาธารณสุขว่าด้วยเงินบำรุงของหน่วยบริการ ในสังกัดกระทรวงสาธารณสุข พ.ศ. ๒๕๖๒ และที่แก้ไขเพิ่มเติม 4. พระราชบัญญัติวินัยการเงินการคลังของรัฐ พ.ศ. 2561 และความรู้เบื้องต้นเกี่ยวกับวิธีการงบประมาณ 5. ระเบียบกระทรวงการคลังว่าด้วยการเบิกเงินจากคลัง การรับเงิน การจ่ายเงิน การเก็บรักษาเงิน และการนำเงินส่งคลัง พ.ศ. ๒๕๖๒ และที่แก้ไขเพิ่มเติม 5. ความรู้เกี่ยวกับระบบบริหารการเงินการคลังภาครัฐแบบอิเล็กทรอนิกส์ใหม่ (New GFMIS Thai) 6. พระราชบัญญัติการปฏิบัติราชการทางอิเล็กทรอนิกส์ พ.ศ. 2565 7. ความรู้เบื้องต้นเกี่ยวกับการบัญชี 8. ความรู้เกี่ยวกับวิสัยทัศน์ พันธกิจ ค่านิยม โครงสร้างกรม และหน่วยงานในสังกัดกรมการแพทย์",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ซึ่งไม่จำเป็นต้องใช้ผู้สำเร็จการศึกษาระดับปริญญา ปฏิบัติงานด้านการเงินและบัญชี ตามแนวทาง แบบอย่าง ขั้นตอน และวิธีการที่ชัดเจน ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ 1. ด้านการปฏิบัติการ (1) จัดทำและปฏิบัติงานด้านเอกสารทางการเงินและบัญชีในระดับต้น เพื่อให้งานเป็นไปตามเป้าหมายที่กำหนด (2) รวบรวมรายละเอียดการจัดทำงบประมาณ เพื่อใช้ประกอบในการทำงบประมาณประจำปีของหน่วยงาน (3) ตรวจสอบและดูความถูกต้องของเอกสารสำคัญทางการเงิน เพื่อให้เกิดความถูกต้องในการปฏิบัติงาน 2. ด้านการบริการ (1) ให้คำแนะนำ ตอบปัญหา ชี้แจงเกี่ยวกับงานด้านการเงินและบัญชี แก่เจ้าหน้าที่ ระดับรองลงมา หน่วยงานราชการ เอกชน และประชาชนทั่วไป เพื่อถ่ายทอดความรู้ ความชำนาญแก่ผู้ที่สนใจ (2) ประสานงานในระดับฝ่ายหรือกลุ่ม กับหน่วยงานราชการ เอกชน หรือประชาชนทั่วไป เพื่อขอความช่วยเหลือและความร่วมมือในงานด้านการเงินและบัญชี และแลกเปลี่ยนความรู้ความเชี่ยวชาญ ที่เป็นประโยชน์ต่อการทำงานของหน่วยงาน (3) ประสานงานในระดับฝ่ายหรือกลุ่ม กับหน่วยงานราชการ เอกชน หรือประชาชนทั่วไป เพื่อขอความช่วยเหลือและร่วมมือในงาน และแลกเปลี่ยนความรู้ ความเชี่ยวชาญที่เป็นประโยชน์ต่อการทำงาน ของหน่วยงาน",
    "แหล่งที่มา": "job.ocsc.go.th",
    "สถานะ": "ปิดรับแล้ว",
