    "คุณสมบัติเฉพาะ": "1) ความรู้เกี่ยวกับการบริหารและการพัฒนาทรัพยากรบุคคลภาครัฐ 2) ความรู้ความเข้าใจเกี่ยวกับกฎหมายและระเบียบที่เกี่ยวข้องกับลักษณะงานที่ปฏิบัติ ได้แก่ (1) พระราชบัญญัติระเบียบข้าราชการพลเรือน พ.ศ. 2551 และที่แก้ไขเพิ่มเติม (2) พระราชบัญญัติระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534 และที่แก้ไขเพิ่มเติม (3) พระราชบัญญัติมาตรฐานทางจริยธรรม พ.ศ. 2562 (4) พระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 (5) พระราชกฤษฎีกาว่าด้วยหลักเกณฑ์และวิธีการบริหารกิจการบ้านเมืองที่ดี พ.ศ. 2546 และที่แก้ไขเพิ่มเติม (6) ระเบียบสำนักนายกรัฐมนตรีว่าด้วยงานสารบรรณ พ.ศ. 2526 และที่แก้ไขเพิ่มเติม (7) ระเบียบสำนักนายกรัฐมนตรีว่าด้วยการลาของข้าราชการ พ.ศ. 2555 และที่แก้ไขเพิ่มเติม (8) ระเบียบว่าด้วยการรักษาความลับของทางราชการ พ.ศ. 2544 และที่แก้ไขเพิ่มเติม 3) ความรู้เกี่ยวกับกรมทรัพยากรน้ำบาดาล",
