    "คุณสมบัติเฉพาะ": "1) วิสัยทัศน์ พันธกิจ อำนาจหน้าที่ นโยบายและยุทธศาสตร์ของกรมทรัพยากรน้ำบาดาล 2) ความรู้เกี่ยวกับการวางแผนเชิงกลยุทธ์ แผนงาน โครงการ การติดตามและประเมินผล การบริหารจัดการ 3) ความรู้เกี่ยวกับสถานการณ์ด้านเศรษฐกิจ สังคม และการเมือง 4) ความรู้เกี่ยวกับทักษะภาษาอังกฤษและงานวิเทศสัมพันธ์ 5) ความรู้เกี่ยวกับพระราชบัญญัติวิธีการงบประมาณ พ.ศ. 2561 6) ความรู้เกี่ยวกับระเบียบว่าด้วยการบริหารงบประมาณ พ.ศ. 2562 และที่แก้ไขเพิ่มเติม",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ที่ต้องใช้ความรู้ ความสามารถทางวิชาการ ในการทำงาน ปฏิบัติงานด้านวิเคราะห์นโยบายและแผน ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย",
