    "จังหวัด": "กรุงเทพมหานคร",
    "ระดับการศึกษา": "ปวส., อนุปริญญา | ประกาศนียบัตรวิชาชีพชั้นสูงหรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกัน \nในทุกสาขาวิชา หรือได้รับอนุปริญญาหลักสูตร 3 ปี หรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกัน \nในทุกสาขาวิชา\n",
