    "วันสัมภาษณ์": "",
    "ลิงก์": "https://prd.thaijobjob.com",
    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10592.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/002.png",
    "คุณสมบัติเฉพาะ": "หลักสูตรและวิธีการสอบแข่งขัน (1) การสอบแข่งขันเพื่อวัดความรู้ความสามารถที่ใช้เฉพาะตำแหน่ง (คะแนนเต็ม 200 คะแนน) ทดสอบความรู้ความสามารถโดยวิธีการสอบข้อเขียน 1. ทดสอบวิชาความรู้ทั่วไปเกี่ยวกับกรมประชาสัมพันธ์ 2. ทดสอบความรู้ความสามารถด้านงานธุรการ โดยมีประเด็นเนื้อหา ดังนี้ - ระเบียบงานสารบรรณ/สารบรรณอิเล็กทรอนิกส์ - ระเบียบพัสดุ ครุภัณฑ์ (2) การสอบแข่งขันเพื่อวัดความเหมาะสมกับตำแหน่ง (คะแนนเต็ม 100 คะแนน) เป็นการทดสอบเพื่อวัดความเหมาะสมกับตำแหน่งที่จะบรรจุและแต่งตั้ง โดยวิธีการสัมภาษณ์หรือวิธีอื่น เพื่อประเมินความเหมาะสมกับตำแหน่ง จากประวัติส่วนตัว ประวัติการศึกษา ประวัติการทำงาน ประสบการณ์ ท่วงทีวาจา อุปนิสัย อารมณ์ ทัศนคติ การปรับตัวเข้ากับผู้ร่วมงาน สังคม และสิ่งแวดล้อม ความคิดริเริ่มสร้างสรรค์ ปฏิภาณไหวพริบ บุคลิกภาพและพฤติกรรมของผู้สอบแข่งขัน เพื่อให้ได้บุคคล ที่มีคุณธรรม จริยธรรม ความรู้ความสามารถ ทักษะ สมรรถนะ และอื่น ๆ ที่จำเป็นสำหรับตำแหน่",
    "รายละเอียดงาน": "หน้าที่ความรับผิดชอบหลัก ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับตนซึ่งไม่จำเป็นตองใชผู้สำเร็จการศึกษาระดับปริญญา ปฏิบัติงานด้านธุรการ สารบรรณ หรือบริการทั่วไป ตามแนวทางแบบอย่าง ขั้นตอน และวิธีการที่ชัดเจน ภายใตการกำกับ แนะนํา ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ 1. ด้านการปฏิบัติการ (1) ปฏิบัติงานธุรการ งานสารบรรณ งานบริการทั่วไป เชน การรับสง ลงทะเบียน ร่างหนังสือโตตอบ จัดเตรียมการประชุม การบันทึกข้อมูล เพื่อสนับสนุนใหงานต่าง ๆ ดำเนินไปได้ โดยสะดวกราบรื่น และมีหลักฐานตรวจสอบได้ (2) รวบรวมข้อมูล จัดเก็บขอมูลสถิติ เอกสารหลักฐานหนังสือ ตามระเบียบวิธีปฏิบัติ เพื่อสะดวกตอการคนหา และเป็นหลักฐานทางราชการ (3) ดำเนินการเกี่ยวกับพัสดุ ครุภัณฑ์ของสำนักงาน เพื่อให้มีอุปกรณ์ที่มีคุณภาพไว้ใช้งาน และอยู่ในสภาพพร้อมใช้งาน (4) รวบรวมรายงานผลการปฏิบัติงานและขอมูลต่าง ๆ นำเสนอต่อผู้บังคับบัญชา เพื่อนําไปใชเสนอแนะและปรับปรุงการปฏิบัติงานตอไป 2. ด้านการบริการ (1) ติดตอประสานงานกับบุคคลภายในหน่วยงานเดียวกันหรือหน่วยงานที่เกี่ยวของ เพื่อใหการปฏิบัติงานเป็นไปด้วยความราบรื่น (2) ให้บริการขอมูลแกผู้มาติดตอราชการเพื่อให้ไดรับขอมูลที่จะนําไปใชประโยชนไดตอไป (3) ผลิตเอกสารตาง ๆ เพื่อสนับสนุนการปฏิบัติงานตามภารกิจของหนวยงาน และปฏิบัติหนาที่อื่นที่เกี่ยวของตามที่ไดรับมอบหมาย",
