    "ระดับการศึกษา": "ปวส., อนุปริญญา | ประกาศนียบัตรวิชาชีพชั้นสูง หรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกัน \nในสาขาวิชาไฟฟ้ากำลัง สาขาวิชาอิเล็กทรอนิกส์ สาขาวิชาเทคโนโลยีโทรคมนาคม สาขาวิชาเทคโนโลยีคอมพิวเตอร์ หรือสาขาวิชาเทคโนโลยีสารสนเทศ หรือได้รับอนุปริญญาหลักสูตร 3 ปี หรือคุณวุฒิ\nอย่างอื่นที่เทียบได้ในระดับเดียวกัน ในสาขาวิชาเทคโนโลยีอิเล็กทรอนิกส์ สาขาวิชาสารสนเทศศาสตร์ หรือสาขาวิชาใดสาขาวิชาหนึ่ง ทางไฟฟ้า ทางไฟฟ้ากำลัง ทางอิเล็กทรอนิกส์ ทางเทคโนโลยีโทรคมนาคม หรือทางคอมพิวเตอร์\n",
