    "คุณสมบัติเฉพาะ": "หลักสูตรและวิธีการสอบแข่งขัน (1) การสอบแข่งขันเพื่อวัดความรู้ความสามารถที่ใช้เฉพาะตำแหน่ง (คะแนนเต็ม 200 คะแนน) ทดสอบความรู้ความสามารถโดยวิธีการสอบข้อเขียน 1. ทดสอบวิชาความรู้ทั่วไปเกี่ยวกับกรมประชาสัมพันธ์ 2. ทดสอบความรู้ความสามารถด้านไฟฟ้า โดยมีประเด็นเนื้อหา ดังนี้ - ความรู้พื้นฐานเกี่ยวกับไฟฟ้า และอิเล็กทรอนิกส์ - ความรู้พื้นฐานเกี่ยวกับระบบเสียง และระบบภาพ - ความรู้พื้นฐานเกี่ยวกับระบบวิทยุกระจายเสียง และระบบวิทยุโทรทัศน์ - ระบบสายส่งกําลัง ระบบสายอากาศ และระบบเชื่อมโยงสัญญาณ - ความรู้พื้นฐานเกี่ยวกับระบบเครือข่ายคอมพิวเตอร์ อุปกรณ์ และระบบอินเทอร์เน็ต - การประยุกต์ใช้งานคอมพิวเตอร์ในงานวิทยุกระจายเสียง และงานวิทยุโทรทัศน์ - ความรู้พื้นฐานเกี่ยวกับเทคโนโลยีสารสนเทศ และมัลติมีเดีย - ความรู้พื้นฐานเกี่ยวกับระบบไฟฟ้ากําลัง ระบบแสงสว่าง และระบบเครื่องปรับอากาศ (2) การสอบแข่งขันเพื่อวัดความเหมาะสมกับตำแหน่ง (คะแนนเต็ม 100 คะแนน) เป็นการทดสอบเพื่อวัดความเหมาะสมกับตำแหน่งที่จะบรรจุและแต่งตั้ง โดยวิธีการสัมภาษณ์หรือวิธีอื่น เพื่อประเมินความเหมาะสมกับตำแหน่ง จากประวัติส่วนตัว ประวัติการศึกษา ประวัติการทำงาน ประสบการณ์ ท่วงทีวาจา อุปนิสัย อารมณ์ ทัศนคติ การปรับตัวเข้ากับผู้ร่วมงาน สังคม และสิ่งแวดล้อม ความคิดริเริ่มสร้างสรรค์ ปฏิภาณไหวพริบ บุคลิกภาพและพฤติกรรมของผู้สอบแข่งขัน เพื่อให้ได้บุคคล ที่มีคุณธรรม จริยธรรม ความรู้ความสามารถ ทักษะ สมรรถนะ และอื่น ๆ ที่จำเป็นสำหรับตำแหน่ง",
    "รายละเอียดงาน": "หน้าที่ความรับผิดชอบหลัก ปฏิบัติงานทางช่างไฟฟ้า ซึ่งมีลักษณะงานที่ปฏิบัติเกี่ยวกับ ตรวจ ทดสอบ สร้าง ซ่อม ประกอบ ดัดแปลง ติดตั้ง และบํารุงรักษา เครื่องจักร เครื่องมือ เครื่องใช้ที่เกี่ยวกับไฟฟ้า คํานวณราคา และประมาณราคาในการดําเนินงานดังกล่าว จัดเก็บรักษา เบิกจ่าย เครื่องมือ เครื่องใช้ และวัสดุอุปกรณ์ที่ใช้ในการปฏิบัติงาน เป็นต้น หรือตําแหน่งที่ปฏิบัติงานด้านช่างไฟฟ้า และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ 1. ด้านการปฏิบัติการ (1) ดูแลบำรุงรักษา และใช้งานเครื่องมือ อุปกรณ์ เครื่องจักรกลไฟฟ้า ระบบไฟฟ้า ระบบเครื่องปรับอากาศ ระบบไฟฟ้าสื่อสารและโทรคมนาคม ระบบสารสนเทศ ระบบควบคุมอัตโนมัติ ระบบอิเล็กทรอนิกส์ ระบบคอมพิวเตอร์ รับส่งข้อมูลข่าวสาร ในภารกิจที่เกี่ยวข้อง (2) จัดทำทะเบียน รวบรวม และจัดเก็บข้อมูลทางสถิติของการใช้งาน เพื่อสนับสนุน การวางแผนบำรุงรักษา (3) ปรับเทียบค่ามาตรฐานตามภารกิจที่เกี่ยวข้อง ตามที่หน่วยงาน หรือกฎหมายกำหนด 2. ด้านการบริการ (1) ให้คำแนะนำ ตอบปัญหา แก้ไขปัญหา ให้แก่ผู้ใช้งานและผู้รับบริการ ทั้งภายใน และภายนอกหน่วยงานในงานที่รับผิดชอบ เพื่อให้สามารถใช้งานได้อย่างถูกต้อง และมีประสิทธิภาพ (2) ประสาน แลกเปลี่ยนความรู้ และข้อมูลต่าง ๆ ทั้งภายในและภายนอกหน่วยงาน เพื่อประกอบการปฏิบัติงานได้อย่างครอบคลุม และมีประสิทธิภาพ",
