    "ระดับการศึกษา": "ปวส. | (1)\tได้รับประกาศนียบัตรวิชาชีพชั้นสูง (ปวส.) หรือคุณวุฒิอย่างอื่นที่เทียบได้\nในระดับเดียวกันในสาขาวิชาเครื่องกล สาขาวิชาไฟฟ้ากำลัง สาขาวิชาอิเล็กทรอนิกส์ สาขาวิชาเครื่องมือวัดและควบคุม สาขาวิชาเทคนิคอุตสาหกรรม หรือสาขาวิชาเทคโนโลยีคอมพิวเตอร์\n(2)\tเป็นผู้สอบผ่านการวัดความรู้ความสามารถทั่วไป ของสำนักงาน ก.พ. ระดับประกาศนียบัตรวิชาชีพชั้นสูง (ปวส.) ขึ้นไป ของสำนักงาน ก.พ. (หากผู้สมัครสอบรายใดใช้หนังสือรับรองผลการสอบผ่าน\nการวัดความรู้ความสามารถทั่วไป ของสำนักงาน ก.พ. ในระดับที่สูงกว่าวุฒิที่รับสมัคร ให้แนบสำเนาปริญญาบัตร และสำเนาระเบียนแสดงผลการศึกษา (Transcript of Records) ของวุฒิที่ใช้ในการสอบเพื่อวัดความรู้ความสามารถทั่วไป มาด้วย)         \n",
