    "คุณสมบัติเฉพาะ": "(1) ความรู้ทั่วไปเกี่ยวกับอำนาจหน้าที่ของกรมการค้าภายใน (2) ความรู้ทั่วไปเกี่ยวกับกฎหมายชั่งตวงวัด และบริหารงานชั่งตวงวัดของกรมการค้าภายใน (3) ความรู้พื้นฐานทางด้านวิทยาศาสตร์ โดยเน้นเนื้อหาความรู้ด้านกลศาสตร์ไฟฟ้า และอิเล็กทรอนิกส์",
    "รายละเอียดงาน": "1) ลักษณะงานที่ปฏิบัติ ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ซึ่งไม่จำเป็นต้องใช้ผู้สำเร็จการศึกษาระดับปริญญาปฏิบัติงานชั่งตวงวัด ตามแนวทาง แบบอย่าง ขั้นตอน และวิธีการที่ชัดเจนภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ ด้านการปฏิบัติการ (1) ตรวจสอบให้คำรับรองเครื่องชั่งตวงวัดที่มีระบบการทำงานไม่ซับซ้อน และการแสดงปริมาณของสินค้าหีบห่อ เพื่อควบคุมให้เป็นไปตามมาตรฐานที่กฎหมายกำหนด (2) ตรวจสอบคำขอเกี่ยวกับการประกอบธุรกิจ ผลิต สั่ง ซ่อม และขายเครื่องชั่งตวงวัด คำขออนุญาตนำเครื่องชั่งตวงวัดเข้ามาในราชอาณาจักร รวมทั้งคำขอจดทะเบียนเครื่องหมายเฉพาะตัว เพื่อควบคุมการประกอบธุรกิจเกี่ยวกับเครื่องชั่งตวงวัดให้เป็นไปตามที่กฎหมายกำหนด (3) ช่วยศึกษา ค้นคว้า เพื่อปรับปรุงหรือกำหนดมาตรฐานของเครื่องชั่งตวงวัดและการแสดงปริมาณของสินค้าหีบห่อ (4) จัดทำทะเบียนผู้ประกอบธุรกิจ จัดทำทะเบียนประวัติเครื่องชั่งตวงวัด เพื่อการติดตามตรวจสอบให้คำรับรอง ด้านการบริการ ชี้แจง ตอบปัญหา และให้คำแนะนำเกี่ยวกับกฎ ระเบียบที่เกี่ยวข้อง และความรู้เกี่ยวกับการชั่งตวงวัดให้แก่ผู้ประกอบการ บุคคลทั่วไป รวมทั้งหน่วยงานที่เกี่ยวข้อง เพื่อให้ผู้รับบริการได้รับข้อมูลและสามารถดำเนินการให้ถูกต้องตามกฎหมาย",
