    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/116.png",
    "คุณสมบัติเฉพาะ": "1. ความรู้ทั่วไปเกี่ยวกับอำนาจหน้าที่กรมการค้าภายใน 2. ความรู้เกี่ยวกับระเบียบสำนักนายกรัฐมนตรีว่าด้วยกองทุนรวมเพื่อช่วยเหลือเกษตรกร พ.ศ. 2534 และที่แก้ไขเพิ่มเติม 3. ความรู้เกี่ยวกับการเงินและบัญชี 4. ระเบียบกระทรวงการคลังว่าด้วยการเบิกเงินจากคลัง การรับเงิน การจ่ายเงิน การเก็บรักษาเงิน และการนำเงินส่งคลัง พ.ศ. 2562 และที่แก้ไขเพิ่มเติม 5. พระราชบัญญัติวิธีการงบประมาณ พ.ศ. 2561",
    "รายละเอียดงาน": "1. จัดทำบัญชี เอกสารรายงานความเคลื่อนไหวทางการเงินของกองทุน เพื่อแสดงสถานะทางการเงิน และใช้เป็นฐานข้อมูลที่ถูกต้องตามระเบียบวิธีการบัญชีของส่วนราชการ 2. บริหารการรับและจ่ายเงิน รายงานสถานะทางการเงิน ตรวจสอบและรวบรวมเอกสารสำคัญ การรับ - จ่ายเงินกองทุนอย่างมีประสิทธิภาพ และถูกต้องตามระเบียบปฏิบัติของทางราชการ 3. จัดเก็บข้อมูลเบื้องต้น ทำสถิติปรับปรุงหรือจัดทำฐานข้อมูลหรือระบบสารสนเทศ ที่เกี่ยวกับงานการเงินและบัญชีเพื่อให้สอดคล้องและสนับสนุนภารกิจของกองทุนและใช้ประกอบการพิจารณากำหนดนโยบาย แผนงาน หลักเกณฑ์และมาตรการต่าง ๆ 4. ให้คำแนะนำ ตอบปัญหาและชี้แจงเกี่ยวกับงานการเงินและบัญชีแก่ผู้มีส่วนได้ส่วนเสีย และผู้รับบริการ 5. ปฏิบัติงานอื่นตามที่ได้รับมอบหมาย",
