    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10629.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/168.png",
    "คุณสมบัติเฉพาะ": "ได้รับประกาศนียบัตรวิชาชีพชั้นสูง ในสาขาวิชาบริหารธุรกิจ การบัญชี การตลาด การเลขานุการ คอมพิวเตอร์ธุรกิจ การเงินการธนาคาร การจัดการทั่วไป การจัดการสำนักงาน",
    "รายละเอียดงาน": "ปฏิบัติงานธุรการและงานสารบรรณ ซึ่งมีลักษณะงานที่เกี่ยวกับการร่าง โต้ตอบ บันทึก ย่อเรื่อง ตรวจทานหนังสือ การดำเนินการเกี่ยวกับเอกสารสิทธิ์ในทรัพย์สินของทางราชการ การดำเนินการเกี่ยวกับพัสดุ ครุภัณฑ์ การตรวจสอบหรือเปลี่ยนแปลงรายการและเก็บรักษาเอกสารสำคัญของทางราชการ การรวบรวม ข้อมูลหรือจัดเตรียมเอกสาร การเตรียมการประชุมและจดบันทึกรายงานการประชุม และปฏิบัติงานหน้าที่อื่นที่ เกี่ยวข้อง ๑) ด้านการปฏิบัติการ (๑) ปฏิบัติงานธุรการ งานสารบรรณ งานบริการทั่วไป เซน การรับส่ง ลงทะเบียน ร่างหนังสือ โต้ตอบจัดเตรียมการประชุม การบันทึกข้อมูล เพื่อสนับสนุนให้งานต่างๆ ดำเนินไปได้ โดยสะดวกราบรื่น และมีหลักฐานตรวจสอบได้ (๒) รวบรวมข้อมูล จัดเก็บข้อมูลสถิติ เอกสาร หลักฐานหนังสือ ตามระเบียบวิธีปฏิบัติ เพื่อสะดวก ต่อการค้นหา และเป็นหลักฐานทางราชการ (๓) ดำเนินการเกี่ยวกับพัสดุ ครุภัณฑ์ของสำนักงาน เพื่อให้มีอุปกรณ์ที่มีคุณภาพไว้ใช้งานและอยู่ ในสภาพพร้อมใช้งาน (๔) รวบรวมรายงานผลการปฏิบัติงานและข้อมูลต่างๆ นำเสนอต่อผู้บังคับบัญชา เพื่อนำไปใช้ เสนอแนะและปรับปรุงการปฏิบัติงานต่อไป ๒) ด้านการบริการ (๑) ติดต่อประสานงานกับบุคคลภายในหน่วยงานเดียวกันหรือหน่วยงานที่เกี่ยวข้องเพื่อให้ การปฏิบัติงานเป็นไปด้วยความราบรื่น (๒) ให้บริการข้อมูลแก่ผู้มาติดต่อราชการเพื่อให้ได้รับข้อมูลที่จะนำไปใช้ประโยชน์ได้ต่อไป (๓) ผลิตเอกสารต่างๆ เพื่อสนับสนุนการปฏิบัติงานตามภารกิจของหน่วยงาน และปฏิบัติหน้าที่ อื่นๆ ที่เกี่ยวข้องตามที่ได้รับมอบหมาย",
