    "วันเริ่มสมัคร": "2026-07-06",
    "วันหมดสมัคร": "2026-07-10",
    "วันสอบ": "",
    "วันสัมภาษณ์": "",
    "ลิงก์": "https://hpc2.anamai.moph.go.th/th/news-anamai-2/246304",
    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10632.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/168.png",
    "คุณสมบัติเฉพาะ": "ได้รับประกาศนียบัตรวิชาชีพชั้นสูง (ปวส) หรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกันใน สาขาวิชาการบัญชี สาขาวิชาการเงินและการธนาคาร สาขาวิชาบริหารธุรกิจ สาขาวิชาการตลาด สาขาวิชาการ เลขานุการ สาขาวิชาคอมพิวเตอร์ธุรกิจ สาขาวิชาการจัดการทั่วไป สาขาวิชาการจัดการสำนักงาน",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้นซึ่งไม่จำเป็นต้องใช้ผู้สำเร็จการศึกษาระดับปริญญาปฏิบัติงาน ด้านการเงินและบัญชี ตามแนวทาง แบบอย่าง ขั้นตอน และวิธีการที่ชัดเจน ภายใต้ การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่าง ๆ ดังนี้ ๑. ด้านการปฏิบัติการ ๑. ปฏิบัติงานเกี่ยวกับการตรวจสอบและวิเคราะห์การรับ-จ่ายเงินประจำวัน และบันทึกข้อมูลทาง การเงินและบัญชี ในระบบ New GFMIS Thai ๒. ปฏิบัติงานบันทึกบัญชีแยกประเภทและทะเบียนคุมต่าง ๆ ทุกประเภทในเครื่องคอมพิวเตอร์ ๓. ปฏิบัติงานการรับและนำส่งเงินรายได้ รายได้แผ่นดิน เบิกเกินส่งคืนต่าง ๆ และการปรับปรุง บัญชีทุกประเภทในระบบ New GFMIS Thai ๔. ปฏิบัติงานการเบิก-จ่ายเงินนอกงบประมาณ (ธกส) ในระบบ New GFMIS Thai ๕. จัดทำรายงานการเงินและบัญชีในระบบ New GFMIS Thai ประจำเดือน ประจำปี และรายงาน ต่าง ๆ ที่เกี่ยวข้อง ๖. ปฏิบัติงานการจ่ายเงินงบประมาณและเงินนอกงบประมาณทุกประเภท ตรวจสอบและจ่ายเงิน ตามเอกสารใบสำคัญจ่าย และทำการจ่ายในระบบ New GFMIS Thai ๗. ปฏิบัติงานการรับ-จ่ายเงิน การเก็บรักษาเงินสดและจัดทำรายงานเงินคงเหลือประจำวัน ๘. ปฏิบัติงานการล้างหนี้เงินยืมทุกประเภทในระบบ New GFMIS Thai ๙. ติดต่อประสานงาน ร่าง-โต้ตอบหนังสือ ตอบปัญหา และชี้แจงเรื่องต่าง ๆ เกี่ยวกับงานในหน้าที่ ๑๐. ปฏิบัติงานอื่นๆ ตามที่ได้รับมอบหมาย ๒. ด้านการบริการ ๑. ให้คำแนะนำ ตอบปัญหา ชี้แจงเกี่ยวกับงานการเงินและบัญชี แก่เจ้าหน้าที่ระดับรองลงมา หน่วยงานราชการ เอกชน และประชาชนทั่วไป เพื่อถ่ายทอดความรู้ ความชำนาญแก่ผู้ที่สนใจ ๒. ประสานงานในระดับกลุ่ม กับหน่วยงานราชการ เอกชน หรือประชาชนทั่วไปเพื่อขอความ ช่วยเหลือและความร่วมมือในงานการเงินและบัญชี และแลกเปลี่ยนความรู้ความเชี่ยวชาญที่เป็นประโยชน์ต่อ การทำงานของหน่วยงาน",
