    "วันสอบ": "",
    "วันสัมภาษณ์": "",
    "ลิงก์": "https://md.thaijobjob.com",
    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10661.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/084.png",
    "คุณสมบัติเฉพาะ": "มีคุณวุฒิอย่างใดอย่างหนึ่งจากสถานศึกษาที่หน่วยงานผู้มีหน้าที่รับผิดชอบหรือ ก.พ. รับรองแล้ว ดังต่อไปนี้ 1. ได้รับประกาศนียบัตรวิชาชีพ ในทุกสาขาวิชา 2. ได้รับประกาศนียบัตรวิชาเทคนิค ในทุกสาขาวิชา 3. ได้รับอนุปริญญาหลักสูตร 2 ปี ต่อจากประกาศนียบัตรมัธยมศึกษาตอนปลายหรือเทียบเท่า ในทุกสาขาวิชา 4. ได้รับประกาศนียบัตรวิชาชีพชั้นสูง ในทุกสาขาวิชา 5. ได้รับอนุปริญญาหลักสูตร 3 ปี ต่อจากประกาศนียบัตรมัธยมศึกษาตอนปลายหรือเทียบเท่า ในทุกสาขาวิชา 6. ได้รับประกาศนียบัตรหรือคุณวุฒิอย่างอื่นที่ ก.พ. กำหนดว่าใช้เป็นคุณสมบัติเฉพาะสำหรับตำแหน่งนี้ได้",
    "รายละเอียดงาน": "1. ปฏิบัติงานขั้นต้นเกี่ยวกับงานพัสดุในการจัดซื้อ จัดจ้าง การควบคุมและดูแลพัสดุ การเก็บ การบันทึก การเบิกจ่าย การยืม การตรวจสอบ การบำรุงรักษาและจำหน่ายพัสดุ 2. ทำทะเบียนการเบิกจ่ายพัสดุ การเก็บรักษาใบสำคัญหลักฐานและเอกสารเกี่ยวกับการพัสดุ เพื่อรวบรวมไว้เป็นข้อมูลในการดำเนินงาน 3. ร่างและตรวจสัญญาซื้อ สัญญาจ้าง หนังสือโต้ตอบ บันทึกย่อเรื่องเกี่ยวกับงานพัสดุ เพื่อเป็นหลักฐานในการดำเนินงาน รายงานสรุปความเห็นเกี่ยวกับงานพัสดุ เพื่อจัดทำรายงานและนำเสนอผู้บังคับบัญชาในหน่วยงาน 4. ประสานงานกับบุคคลภายในหน่วยงาน ต่างหน่วยงานหรือประชาชนทั่วไป เพื่อให้บริการหรือ ขอความช่วยเหลือในงานที่ตนรับผิดชอบ 5. ปฏิบัติงานอื่นที่เกี่ยวข้องหรือตามที่ผู้บังคับบัญชามอบหมาย",
