    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/084.png",
    "คุณสมบัติเฉพาะ": "มีคุณวุฒิอย่างใดอย่างหนึ่งจากสถานศึกษาที่หน่วยงานผู้มีหน้าที่รับผิดชอบหรือ ก.พ. รับรองแล้ว ดังต่อไปนี้ 1. ได้รับประกาศนียบัตรวิชาชีพ ในประเภทวิชาบริหารธุรกิจ สาขาวิชาการบัญชี หรือ สาขาวิชาการเงินและการธนาคาร 2. ได้รับประกาศนียบัตรวิชาเทคนิค ในประเภทวิชาบริหารธุรกิจ สาขาวิชาการบัญชี หรือ สาขาวิชาการเงินและการธนาคาร 3. ได้รับอนุปริญญาหลักสูตร 2 ปี ต่อจากประกาศนียบัตรมัธยมศึกษาตอนปลายหรือเทียบเท่า ในประเภทวิชาบริหารธุรกิจ สาขาวิชาการบัญชี หรือ สาขาวิชาการเงินและการธนาคาร 4. ได้รับประกาศนียบัตรวิชาชีพชั้นสูง ในประเภทวิชาบริหารธุรกิจ สาขาวิชาการบัญชี หรือ สาขาวิชาการเงินและการธนาคาร 5. ได้รับอนุปริญญาหลักสูตร 3 ปี ต่อจากประกาศนียบัตรมัธยมศึกษาตอนปลายหรือเทียบเท่า ในประเภทวิชาบริหารธุรกิจ สาขาวิชาการบัญชี หรือ สาขาวิชาการเงินและการธนาคาร 6. ได้รับประกาศนียบัตรหรือคุณวุฒิอย่างอื่นที่ ก.พ. กำหนดว่าใช้เป็นคุณสมบัติเฉพาะสำหรับตำแหน่งนี้ได้",
    "รายละเอียดงาน": "1. จัดทำและปฏิบัติงานด้านเอกสารทางการเงินและบัญชี เพื่อให้งานเป็นไปตามเป้าหมายที่กำหนด 2. รวบรวมรายละเอียดการจัดทำงบประมาณ เพื่อใช้ในการทำงบประมาณประจำปีของหน่วยงาน 3. ตรวจสอบและดูความถูกต้องของเอกสารสำคัญทางการเงิน เพื่อให้เกิดความถูกต้องในการปฏิบัติงาน 4. ปฏิบัติงานเกี่ยวกับการรับ - จ่ายเงิน ให้คำแนะนำ ตอบปัญหา ชี้แจงเกี่ยวกับงานการเงินและบัญชี 5. ปฏิบัติงานอื่นที่เกี่ยวข้อง หรือตามที่ผู้บังคับบัญชามอบหมาย",
