    "คุณสมบัติเฉพาะ": "คุณสมบัติเฉพาะตำแหน่ง 1. ได้รับประกาศนียบัตรคนใช้เครื่องจักรยนต์ชั้นสอง หรือ ประกาศนียบัตรลูกเรือเข้ายามฝ่ายช่างกลของเรือเดินทะเล หรือ ประกาศนียบัตรแสดงความรู้ความชำนาญลูกเรือเข้ายามฝ่ายช่างกล (กรณีเรือกลเดินทะเลระหว่างประเทศ) และ 2. มีประสบการณ์เกี่ยวกับการซ่อมเครื่องยนต์มาแล้วไม่น้อยกว่า 1 ปี และ 3. มีความสามารถในการว่ายน้ำ หมายเหตุ กรณีนำประกาศนียบัตรชั้นสูงกว่ามายื่นแทน ให้ได้รับอัตราค่าตอบแทนตามระดับชั้นที่กำหนดในข้อ 1",
    "รายละเอียดงาน": "1. ควบคุมเครื่องจักรยนต์เรือ ในการออกปฏิบัติงาน สำรวจ ตรวจตรา ปราบปราม 2. ซ่อม บำรุงรักษา ติดตั้งเครื่องจักรเรือ เพื่อให้มีความพร้อม สามารถออกไปปฏิบัติงานได้ตลอดเวลา 3. ตรวจสภาพเครื่องมือเครื่องใช้เกี่ยวกับการซ่อมแซมเครื่องจักรยนต์ 4. ปฏิบัติงานอื่นที่เกี่ยวข้อง หรือตามที่ผู้บังคับบัญชามอบหมาย",
