    "รายละเอียดงาน": "1. ปฏิบัติงานเกี่ยวกับการควบคุม ปรับซ่อม และบำรุงรักษาเครื่องจักรกล และเครื่องจักรอื่น ๆ ที่มิได้เกี่ยวข้องกับการไฟฟ้า 2. ตรวจบำรุงรักษาอุปกรณ์ เครื่องมือเครื่องใช้ทุกชนิดของแผนกช่างกล ตรวจในด้านสวัสดิการ และความเป็นระเบียบเรียบร้อยของที่อยู่อาศัยของพนักงานช่างกล 3. ประสานงานกับหน่วยงานอื่นที่เกี่ยวข้อง ช่วยฝึกอบรมและฝึกหัดพนักงานเกี่ยวกับการปรับและซ่อมให้ถูกต้องตามหลักวิชาการ 4. ปฏิบัติงานอื่นที่เกี่ยวข้อง หรือตามที่ผู้บังคับบัญชามอบหมาย",
