    "คุณสมบัติเฉพาะ": "มีคุณวุฒิอย่างใดอย่างหนึ่งจากสถานศึกษาที่หน่วยงานผู้มีหน้าที่รับผิดชอบหรือ ก.พ. รับรองแล้ว ดังต่อไปนี้ 1. ได้ประกาศนียบัตรมัธยมศึกษาตอนต้น หรือ ประกาศนียบัตรมัธยมศึกษาตอนปลาย 2. ได้รับประกาศนียบัตรวิชาชีพ ในประเภทวิชาอุตสาหกรรม ทุกสาขาวิชา 3. ได้รับประกาศนียบัตรวิชาเทคนิค ในประเภทวิชาอุตสาหกรรม ทุกสาขาวิชา 4. ได้รับอนุปริญญาหลักสูตร 2 ปี ต่อจากประกาศนียบัตรมัธยมศึกษาตอนปลายหรือเทียบเท่า ในสาขาวิชาใดสาขาวิชาหนึ่ง ทางเครื่องกล หรือทางเทคโนโลยีเครื่องกล 5. ได้รับประกาศนียบัตรวิชาชีพชั้นสูง ในประเภทวิชาอุตสาหกรรม ทุกสาขาวิชา 6. ได้รับอนุปริญญาหลักสูตร 3 ปี ต่อจากประกาศนียบัตรมัธยมศึกษาตอนปลายหรือเทียบเท่า ในสาขาวิชาใดสาขาวิชาหนึ่ง ทางเครื่องกล หรือทางเทคโนโลยีเครื่องกล และ ได้รับใบอนุญาตเป็นผู้ขับรถตามกฎหมาย (ประเภทใบอนุญาตทุกประเภทชนิดที่สอง) หมายเหตุ สามารถนำใบอนุญาตเป็นผู้ขับรถตามกฎหมายชนิดที่สูงกว่ามายื่นแทนได้",
