    "กระทรวง": "อื่น ๆ",
    "ประเภทงาน": "อื่น ๆ (พนักงานกองทุน)",
    "ระดับ": "ไม่มีข้อมูล",
    "วิธีการสรรหา": "สอบแข่งขัน",
    "เงื่อนไข": "อื่น ๆ",
    "เงินเดือนต่ำสุด": "21780",
    "เงินเดือนสูงสุด": "21780",
    "จำนวนรับ": "2",
    "จังหวัด": "กรุงเทพมหานคร",
    "ระดับการศึกษา": "ป.ตรี, ป.โท, ป.เอก | ไม่ต่ำกว่าปริญญาตรีในสาขาวิชา เศรษฐศาสตร์ บริหารธุรกิจ การเงินและการบัญชี นิติศาสตร์ รัฐศาสตร์ วิศวกรรมศาสตร์ วิทยาศาสตร์ หรือคุณวุฒิในสาขาใด สาขาหนึ่งที่สำนักงานบริหารกองทุนเพื่อส่งเสริมการอนุรักษ์พลังงานกำหนด",
    "วันเริ่มสมัคร": "2026-07-14",
    "วันหมดสมัคร": "2026-08-10",
    "วันสอบ": "",
    "วันสัมภาษณ์": "",
    "ลิงก์": "https://enconfund.go.th/content-detail/ca92bd86-c823-4fc8-8580-fd3002e0e342",
    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10694.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/10078.png",
    "คุณสมบัติเฉพาะ": "1. ความรู้ความสามารถทั่วไป 2. ความรู้เกี่ยวกับสำนักงานบริหารกองทุนเพื่อส่งเสริมการอนุรักษ์พลังงาน 3. ความรู้เกี่ยวกับระเบียบสำนักนายกรัฐมนตรี ว่าด้วยงานสารบรรณ พ.ศ. 2526 และที่แก้ไขเพิ่มเติม 4. ความรู้เฉพาะตำแหน่ง",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานในระดับต้น ซึ่งต้องใช้ความรู้ ความสามารถทางวิชาการในการปฏิบัติงาน ปฏิบัติงานด้านการพัสดุภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมายโดยมีลักษณะงานที่ปฏิบัติในด้านต่างๆ ดังนี้ 1. รวบรวมและศึกษาข้อมูลในงานพัสดุ เพื่อกำหนดคุณภาพ และมาตรฐานของพัสดุ 2. ตรวจสอบ และดูแลการจัดซื้อจัดจ้างวิธีต่างๆ เช่น วิธีประกาศเชิญชวนทั่วไป วิธีคัดเลือก และวิธีเฉพาะเจาะจง เพื่อให้เป็นไปตามระเบียบที่กำหนดให้ถือปฏิบัติ 3. จัดทำรายละเอียดบัญชี หรือทะเบียนคุมทรัพย์สินเกี่ยวกับคุณลักษณะเฉพาะของวัสดุ เพื่อให้สามารถตรวจสอบวัสดุต่างๆ ได้โดยสะดวก 4. ซ่อมแซมและดูแลรักษา พัสดุในครอบครองเพื่อให้มีสภาพที่พร้อมใช้งาน 5. จำหน่ายพัสดุเมื่อชำรุดหรือเสื่อมสภาพ หรือไม่จำเป็นในการใช้งานทางราชการอีกต่อไป เพื่อให้พัสดุเกิดประโยชน์ให้แก่ทางราชการได้มากที่สุด 6. ถ่ายทอดความรู้ด้านงานพัสดุแก่เจ้าหน้าที่ระดับรองลงมา เช่น ให้คำแนะนำในการปฏิบัติงาน วางโครงการกำหนดหลักสูตรและฝึกอบรม จัดทำคู่มือประจำสำหรับการฝึกอบรมและวิธีใช้อุปกรณ์เครื่องมือที่ถูกต้อง เป็นต้น เพื่อถ่ายทอดความรู้ที่เป็นประโยชน์ในการปฏิบัติงานตามมาตรฐานและข้อกำหนด 7. วางแผนการทำงานที่รับผิดชอบร่วมดำเนินการวางแผนการทำงานของสำนักงานหรือโครงการเพื่อให้การดำเนินงานเป็นไปตามเป้าหมายผลสัมฤทธิ์ที่กำหนด 8. ประสานการทำงานร่วมกันทั้งภายในและภายนอกทีมงานหรือหน่วยงาน เพื่อให้เกิด ความร่วมมือและผลสัมฤทธิ์ตามที่กำหนดไว้ 9. ชี้แจงและให้รายละเอียดเกี่ยวกับข้อมูล ข้อเท็จจริง แก่บุคคลหรือสำนักงานที่เกี่ยวข้อง เพื่อสร้างความเข้าใจหรือความร่วมมือในการดำเนินงานตามที่ได้รับมอบหมาย 10. ให้คำแนะนำ ตอบปัญหาและชี้แจงเกี่ยวกับงานพัสดุที่ตนมีความรับผิดชอบ ในระดับเบื้องต้นแก่หน่วยงานราชการ เอกชน หรือประชาชนทั่วไป เพื่อให้ผู้ที่สนใจได้ทราบข้อมูลและความรู้ต่างๆ ที่เป็นประโยชน์ 11. จัดเก็บข้อมูลเบื้องต้น ทำสถิติ ปรับปรุง หรือจัดทำฐานข้อมูลหรือระบบสารสนเทศ ที่เกี่ยวกับงานพัสดุเพื่อให้สอดคล้องและสนับสนุนภารกิจของสำนักงานบริหารกองทุนฯ และใช้ประกอบการพิจารณากำหนดนโยบาย แผนงาน หลักเกณฑ์ มาตรการต่างๆ",
