    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/10078.png",
    "คุณสมบัติเฉพาะ": "1. ความรู้ความสามารถทั่วไป 2. ความรู้เกี่ยวกับสำนักงานบริหารกองทุนเพื่อส่งเสริมการอนุรักษ์พลังงาน 3. ความรู้เกี่ยวกับระเบียบสำนักนายกรัฐมนตรี ว่าด้วยงานสารบรรณ พ.ศ. 2526 และที่แก้ไขเพิ่มเติม 4. ความรู้เฉพาะตำแหน่ง",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ที่ต้องใช้ความรู้ความสามารถทางวิชาการในการทำงาน ปฏิบัติงานเกี่ยวกับวิทยาการคอมพิวเตอร์ ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมายโดยมีลักษณะงานที่ได้ปฏิบัติในด้านต่างๆ ดังนี้ 1. ติดตั้งเครื่องคอมพิวเตอร์ส่วนบุคคล ชุดคำสั่งระบบปฏิบัติการ ชุดคำสั่งสำเร็จรูป ระบบเครือข่ายคอมพิวเตอร์และอุปกรณ์เกี่ยวข้อง เพื่ออำนวยการให้งานเทคโนโลยีสารสนเทศในความรับผิดชอบดำเนินไปได้อย่างราบรื่นและสอดคล้องกับความต้องการของสำนักงาน 2. ประมวลผลและปรับปรุงแก้ไขแฟ้มข้อมูล เพื่อให้ข้อมูลที่ได้ถูกต้องแม่นยำมากที่สุด 3. ทดสอบคุณสมบัติด้านเทคนิคของระบบ เพื่อให้ระบบมีคุณสมบัติที่ถูกต้อง ตรงตามความต้องการและสภาพใช้งานของสำนักงานอยู่เสมอ 4. เขียนชุดคำสั่งตามข้อกำหนดของระบบงานประยุกต์ และระบบข้อมูลที่ได้วางแผนไว้แล้ว เพื่อสนับสนุนการปฏิบัติงานเทคโนโลยีสารสนเทศให้ดำเนินไปได้อย่างราบรื่น 5. เขียนชุดคำสั่ง ทดสอบความถูกต้องของคำสั่ง แก้ไขข้อผิดพลาดของคำสั่ง เพื่อให้ระบบ ปฏิบัติการทำงานได้อย่างถูกต้องแม่นยำและมีประสิทธิภาพมากที่สุด 6. ช่วยรวบรวมข้อมูลและวิเคราะห์ความต้องการของระบบงานประยุกต์ และระบบข้อมูลของหน่วยงานที่ไม่ซับซ้อน เพื่อพัฒนาระบบเทคโนโลยีสารสนเทศในสำนักงานให้มีประสิทธิภาพ และตรงตามความต้องการของหน่วยงานมากที่สุด 7. ช่วยรวบรวมข้อมูลและวิเคราะห์ ออกแบบ และพัฒนาระบบงานประยุกต์ เพื่อให้ได้ระบบงานประยุกต์ที่ตรงตามคุณลักษณะและความต้องการของสำนักงาน 8. รวบรวมข้อมูลประกอบการกำหนดคุณลักษณะเฉพาะของเครื่องคอมพิวเตอร์และอุปกรณ์ระบบเครือข่าย ระบบงานประยุกต์และระบบสารสนเทศ การจัดการระบบการทำงานของเครื่อง การติดตั้งระบบเครื่อง เพื่อให้ได้อุปกรณ์คอมพิวเตอร์ที่มีมาตรฐานเดียวกันทั้งสำนักงาน และตรงตามความต้องการ ลักษณะการใช้งานของสำนักงาน 9. วางแผนการทำงานที่รับผิดชอบร่วมดำเนินการวางแผนการทำงานของหน่วยงานหรือโครงการเพื่อให้การดำเนินงานเป็นไปตามเป้าหมายผลสัมฤทธิ์ที่กำหนด 10. ประสานงานทำงานร่วมกันทั้งภายในและภายนอกทีมงานหรือสำนักงาน เพื่อให้เกิดความร่วมมือและผลสัมฤทธิ์ตามที่กำหนดไว้ 11. ชี้แจงและให้รายละเอียดเกี่ยวกับข้อมูล ข้อเท็จจริง แก่บุคคลหรือสำหรับงานที่เกี่ยวข้องเพื่อสร้างความเข้าใจหรือความร่วมมือในการดำเนินงานตามที่ได้รับมอบหมาย 12. ช่วยจัดทำคู่มือระบบและคู่มือผู้ใช้ เพื่ออำนวยความสะดวกแก่ผู้ใช้ให้สามารถใช้งานคอมพิวเตอร์ได้ด้วยตัวเอง 13. ดำเนินการฝึกอบรมหรือถ่ายทอดความรู้ สนับสนุนการใช้ระบบงานที่พัฒนาต่อเจ้าหน้าที่ผู้ใช้งาน หรือเจ้าหน้าที่ระดับรองลงมา 14. ปฏิบัติงานร่วมกับผู้ใช้ในการนำระบบไปใช้ในการปฏิบัติงาน เพื่อช่วยเหลือผู้ใช้หากมีปัญหาหรือข้อสงสัยในการใช้งานคอมพิวเตอร์ และปฏิบัติงานอื่นที่เกี่ยวข้องตามที่ได้รับมอบหมาย",
