    "รายละเอียดงาน": "ลักษณะงานที่ต้องปฏิบัติ 1. ตรวจตราดูแลความเรียบร้อยภายในสนามบิน (Airside) ดูแลความปลอดภัย ให้แก่อากาศยานขณะที่มาทำการบินขึ้น – ลง ที่ท่าอากาศยาน 2. ควบคุมดูแลมให้มี เศษวัสดุ สัตว์ ยานพาหนะ หรือบุคคลเข้าไปในเขตทางวิ่ง ทางขับและลานจอด ดูแลการรุกล้ำแนวเขตสนามบิน บำรุงรักษา ซ่อมแซมสิ่งที่ชำรุดเสียหายเล็กน้อยภายในสนามบิน (Airside) รวมทั้งการรักษาเครื่องมือเครื่องใช้ที่ใช้ให้อยู่ในสภาพที่ใช้งานได้ปกติ 3. จัดทำรายงานการปฏิบัติงานให้ผู้บังคับบัญชาทราบ 4. ปฏิบัติงานอื่นตามที่ได้รับมอบหมาย ทั้งนี้ ต้องมีความพร้อมที่จะสามารถปฏิบัติงานเป็นกะ หรือเป็นผลัดได้",
