    "คุณสมบัติเฉพาะ": "ผู้สมัครสอบต้องได้รับคุณวุฒิประกาศนียบัตรวิชาชีพชั้นสูง (ปวส.) หรืออนุปริญญาหลักสูตร 3 ปี ต่อจากประกาศนียบัตรมัธยมศึกษาตอนปลายหรือเทียบเท่า จากสถาบันการศึกษาที่ ก.พ. รับรองในสาขาวิชาพณิชยการ สาขาวิชาการบัญชี สาขาวิชาการเงินและการธนาคาร สาขาวิชาบริหารธุรกิจ สาขาวิชาการตลาด สาขาวิชาการจัดการทั่วไป สาขาวิชาเลขานุการ สาขาวิชาคอมพิวเตอร์ธุรกิจ สาขาวิชาการจัดการสำนักงาน สาขาวิชาเทคโนโลยีคอมพิวเตอร์",
    "รายละเอียดงาน": "ปฏิบัติงานด้านธุรการ สารบรรณ หรือบริการทั่วไป เช่น การรับส่ง ลงทะเบียน ร่างหนังสือโต้ตอบ จัดเตรียมการประชุม การบันทึกข้อมูล เพื่อสนับสนุนให้งานต่าง ๆ ดำเนินไปได้สะดวกราบรื่นและมีหลักฐานตรวจสอบได้ รวบรวมข้อมูล จัดเก็บข้อมูลสถิติ เอกสาร หลักฐานหนังสือตามระเบียบวิธีปฏิบัติ เพื่อสะดวกต่อการค้นหา และเป็นหลักฐานทางราชการ ดำเนินการเกี่ยวกับพัสดุครุภัณฑ์ของสำนักงาน เพื่อให้มีอุปกรณ์ที่มีคุณภาพไว้ใช้งาน และอยู่ในสภาพพร้อมใช้งานรวบรวมรายงานผลการปฏิบัติงานและข้อมูลต่าง ๆ และให้บริการเอกสารสำคัญของทางราชการ เช่น ทะเบียนประวัติข้าราชการ ทะเบียนที่เกี่ยวข้อง กับการค้าและอุตสาหกรรม งานทะเบียนเกี่ยวกับเอกสารสิทธิต่าง ๆ การรวบรวมข้อมูล หรือจัดเตรียมเอกสาร จดบันทึก รายงานการประชุม เป็นต้น และปฏิบัติงานอื่น ๆ ที่เกี่ยวข้องตามที่ได้รับมอบหมาย",
