    "คุณสมบัติเฉพาะ": "๑) ต้องมีอายุไม่เกิน ๖๕ ปีบริบูรณ์ นับถึงวันปิดรับสมัคร ๒) ได้รับคุณวุฒิไม่ต่ำกว่าปริญญาตรี และมีประสบการณ์ในงานที่จะปฏิบัติเป็นเวลาไม่น้อยกว่า ๑๐ ปี สำหรับวุฒิปริญญาตรี ๘ ปี สำหรับวุฒิปริญญาโท และ ๖ ปี สำหรับวุฒิปริญญาเอก ๓) มีประสบการณ์ด้านการวิเคราะห์ กลั่นกรองงานที่เกี่ยวกับนโยบายสำคัญของรัฐบาล โดยเฉพาะด้านทรัพยากรธรรมชาติและสิ่งแวดล้อม ๔) มีประสบการณ์ด้านการประสานงานเกี่ยวกับภารกิจของรัฐมนตรี คณะรัฐมนตรีและรัฐสภา",
    "รายละเอียดงาน": "๑) ให้คำปรึกษาหน่วยงานในสังกัดกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม เกี่ยวกับการจัดทำเรื่องเข้าสู่การพิจารณาของคณะรัฐมนตรี ให้เป็นไปตามหลักเกณฑ์ที่กำหนดในพระราชกฤษฎีกาว่าด้วย การเสนอเรื่องและการประชุมคณะรัฐมนตรี พ.ศ. ๒๕๔๘ และระเบียบว่าด้วยหลักเกณฑ์และวิธีการเสนอเรื่องและการประชุมคณะรัฐมนตรี พ.ศ. ๒๕๔๘ ๒) ให้คำปรึกษาหน่วยงานในสังกัดกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม เกี่ยวกับการวางแผน การเสนอเรื่องต่อคณะรัฐมนตรี การติดตามการดำเนินการตามมติคณะรัฐมนตรี การทบทวนมติคณะรัฐมนตรี ของกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม ๓) วิเคราะห์ และจัดทำข้อมูลประกอบการตัดสินใจของรัฐมนตรีว่าการกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม และปลัดกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม ในภารกิจที่เกี่ยวข้องกับคณะรัฐมนตรี ๔) ประสานและสนับสนุนข้อมูลการดำเนินงานของกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม ในภารกิจที่เกี่ยวข้องกับคณะรัฐมนตรี ๕) ตรวจสอบการสรุปผลการประชุมคณะกรรมการระดับชาติของกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม/การสรุปเรื่องของกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม ที่กราบเรียนนายกรัฐมนตรี/ รองนายกรัฐมนตรี ที่กำกับกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม ๖) ให้คำปรึกษาแก่ผู้บริหารกระทรวงทรัพยากรธรรมชาติและสิ่งแวดล้อม ในการดำเนินงานที่เกี่ยวข้อง ๗) ปฏิบัติงานอื่นๆ ตามที่ได้รับมอบหมาย",
