    "จังหวัด": "กรุงเทพมหานคร",
    "ระดับการศึกษา": "ป.ตรี, ป.โท, ป.เอก | \tไม่ต่ำกว่าปริญญาตรีในสาขาวิชา เศรษฐศาสตร์ การเงินและการบัญชี บริหารธุรกิจ นิติศาสตร์ วิศวกรรมศาสตร์ วิทยาศาสตร์ รัฐศาสตร์ ศิลปศาสตร์ อุตสาหกรรมศาสตร์ สังคมศาสตร์ หรือคุณวุฒิในสาขาใด สาขาหนึ่งที่สำนักงานบริหารกองทุนเพื่อส่งเสริมการอนุรักษ์พลังงานกำหนด",
    "วันเริ่มสมัคร": "2026-07-14",
    "วันหมดสมัคร": "2026-08-10",
    "วันสอบ": "",
    "วันสัมภาษณ์": "",
    "ลิงก์": "https://enconfund.go.th/content-detail/ca92bd86-c823-4fc8-8580-fd3002e0e342",
    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10694.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/10078.png",
    "คุณสมบัติเฉพาะ": "1. ความรู้ความสามารถทั่วไป 2. ความรู้เกี่ยวกับสำนักงานบริหารกองทุนเพื่อส่งเสริมการอนุรักษ์พลังงาน 3. ความรู้เกี่ยวกับระเบียบสำนักนายกรัฐมนตรี ว่าด้วยงานสารบรรณ พ.ศ. 2526 และที่แก้ไขเพิ่มเติม 4. ความรู้เฉพาะตำแหน่ง",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานที่มีประสบการณ์ โดยใช้ความรู้ ความสามารถ ประสบการณ์ และความชำนาญงานสูงในด้านการวางแผน กำหนดเป้าหมายเชิงนโยบาย ปฏิบัติงานที่ต้องตัดสินใจ หรือแก้ปัญหาที่ยาก และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่างๆ ดังนี้ 1. รวบรวม และวิเคราะห์ข้อมูล ความเห็น ข้อเสนอแนะ ในการทำระบบและหลักเกณฑ์ มาตรฐานด้านต่างๆ เพื่อใช้ในการจัดทำและวิเคราะห์ประมาณการรายจ่ายกองทุนฯ รวมทั้งจัดทำรายงาน ความก้าวหน้ารายไตรมาส และรายงานภาพรวมประจำปี เพื่อประกอบการวิเคราะห์และจัดสรรเงินกองทุนฯ ประจำปี 2. ร่วมศึกษา วิเคราะห์ วิจัย และพัฒนาระบบ รูปแบบ การจัดทำมาตรฐานต้นทุน บัญชีราคามาตรฐานด้านต่างๆ ประมาณการภาระงบประมาณกองทุนฯ โครงสร้าง แผนการจัดสรร เงินกองทุนฯ และกระบวนการจัดทำแผนประมาณการรายจ่าย ในเชิงบูรณาการ เพื่อประกอบการวิเคราะห์และจัดสรรเงินกองทุนประจำปี 3. ร่วมศึกษา วิเคราะห์ ยุทธศาสตร์ นโยบายของรัฐบาล กรอบการขอจัดสรรเงินกองทุน ความสอดคล้องของโครงการกับเป้าหมายการให้บริการของกองทุนฯ ความเป็นไปได้ในการใช้จ่ายเพื่อประกอบการวิเคราะห์และจัดสรรเงินกองทุนประจำปี 4. ร่วมจัดทำประมาณการรายจ่ายประจำปีของกองทุน ประมาณการรายจ่ายเพิ่มเติมเอกสารประกอบ เพื่อเสนอต่อคณะกรรมการ คณะอนุกรรมการและกระทรวงการคลัง ตามกรอบระยะเวลาที่กฎหมายกำหนด 5. ร่วมติดตาม ตรวจสอบ ประเมินผล และรายงานความสำเร็จของการดำเนินโครงการต่างๆ ตามกรอบวงเงินที่ได้รับจัดสรรจากกองทุนฯ และการใช้จ่ายเงินกองทุนที่ได้รับจัดสรรเพื่อให้เกิดประโยชน์ และคุ้มค่าในการใช้จ่ายเงินกองทุนฯ 6. ปฏิบัติงานอื่นๆ ตามที่ผู้บังคับบัญชา หรือคณะกรรมการ/อนุกรรมการกองทุนฯ มอบหมาย",
