    "คุณสมบัติเฉพาะ": "1. ความรู้ความสามารถทั่วไป 2. ความรู้เกี่ยวกับสำนักงานบริหารกองทุนเพื่อส่งเสริมการอนุรักษ์พลังงาน 3. ความรู้เกี่ยวกับระเบียบสำนักนายกรัฐมนตรี ว่าด้วยงานสารบรรณ พ.ศ. 2526 และที่แก้ไขเพิ่มเติม 4. ความรู้เฉพาะตำแหน่ง",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานที่มีประสบการณ์ โดยใช้ความรู้ ความสามารถ ประสบการณ์ และความชำนาญงานสูงในด้านการติดตามประเมินผลและรายงาน ปฏิบัติงานที่ต้องตัดสินใจ หรือแก้ปัญหาที่ยากและปฏิบัติงานอื่นที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติในด้านต่างๆ ดังนี้ 1. รวบรวม และวิเคราะห์ข้อมูล ความเห็น ข้อเสนอแนะ ในการทำระบบและหลักเกณฑ์มาตรฐานด้านต่างๆ เพื่อใช้ในการจัดทำและวิเคราะห์ประมาณการรายจ่ายกองทุนฯ รวมทั้งจัดทำรายงานความก้าวหน้ารายไตรมาส และรายงานภาพรวมประจำปี เพื่อประกอบการวิเคราะห์และจัดสรรเงินกองทุนฯ ประจำปี 2 ร่วมศึกษา วิเคราะห์ วิจัย และพัฒนาระบบ รูปแบบ การจัดทำมาตรฐานต้นทุน บัญชีราคามาตรฐานด้านต่างๆ ประมาณการภาระงบประมาณกองทุนฯ โครงสร้างแผนการจัดสรรเงินกองทุนฯ และกระบวนการจัดทำแผนประมาณการรายจ่ายในเชิงบูรณาการ เพื่อประกอบการวิเคราะห์และจัดสรรเงินกองทุนประจำปี 3. ร่วมศึกษา วิเคราะห์ ยุทธศาสตร์ นโยบายของรัฐบาล กรอบการขอจัดสรรเงินกองทุน ความสอดคล้องของโครงการกับเป้าหมายการให้บริการของกองทุนฯ ความเป็นไปได้ในการใช้จ่าย เพื่อประกอบการวิเคราะห์และจัดสรรเงินกองทุนประจำปี 4. ร่วมจัดทำประมาณการรายจ่ายประจำปีของกองทุน ประมาณการรายจ่ายเพิ่มเติม เอกสารประกอบ เพื่อเสนอต่อคณะกรรมการ คณะอนุกรรมการ และกระทรวงการคลัง ตามกรอบระยะเวลาที่กฎหมายกำหนด 5. ร่วมติดตาม ตรวจสอบ ประเมินผล และรายงานความสำเร็จของการดำเนินโครงการต่างๆ ตามกรอบวงเงินที่ได้รับจัดสรรจากกองทุนฯ และการใช้จ่ายเงินกองทุนที่ได้รับจัดสรร เพื่อให้เกิดประโยชน์และคุ้มค่าในการใช้จ่ายเงินกองทุนฯ 6. ปฏิบัติงานอื่นๆ ตามที่ผู้บังคับบัญชา หรือคณะกรรมการ/อนุกรรมการกองทุนฯ มอบหมาย",
