    "รายละเอียดงาน": "ปฏิบัติหน้าที่เกี่ยวกับการสำรวจ ศึกษา วางแผน วิเคราะห์ ออกแบบ คำนวณ ประมาณราคา ควบคุมงานก่อสร้าง งานบำรุง งานบูรณะซ่อมแซม หรืองานอื่นใดที่เกี่ยวข้อง กับวิศวกรรมโยธาและโครงสร้างพื้นฐาน เพื่อให้เป็นไปตามหลักวิชาการ กฎหมายที่เกี่ยวข้อง ตรวจสอบ แบบแปลน โครงสร้าง สภาพการใช้งานของอาคารหรือโครงสร้างพื้นฐาน เพื่อให้เกิดความปลอดภัย ควบคุม ดูแลการปฏิบัติงานสำรวจ ให้เป็นไปอย่างมีประสิทธิภาพ เพื่อให้ได้รูปแบบ แผนที่ต่าง ๆ ที่ถูกต้อง ศึกษาและทดสอบวัสดุ ที่ใช้ในงานด้านวิศวกรรมโยธาและโครงสร้างพื้นฐาน เพื่อให้มีความมั่นคง แข็งแรง ปลอดภัย และประหยัดงบประมาณให้คำแนะนำ ชี้แจง ตอบปัญหาและเผยแพร่ข้อมูลข่าวสารเกี่ยวกับ งานวิศวกรรมโยธา และโครงสร้างพื้นฐานในความรับผิดชอบในระดับเบื้องต้นแก่หน่วยงานภาครัฐ ภาคเอกชน และประชาชนทั่วไปเพื่อให้ได้ข้อมูลความรู้ต่าง ๆ ที่เป็นประโยชน์ รวมทั้งการมีส่วนร่วม และปฏิบัติหน้าที่อื่นตามที่ได้รับมอบหมาย",
