    "จังหวัด": "กรุงเทพมหานคร",
    "ระดับการศึกษา": "ป.โท | ได้รับปริญญาโทหรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกัน ในสาขาวิชาใดสาขาวิชาหนึ่ง ทางบรรณารักษศาสตร์ ทางบรรณารักษศาสตร์และสารนิเทศศาสตร์ ทางบรรณารักษศาสตร์และสารสนเทศศาสตร์ ทางสารสนเทศศึกษา หรือทางสารนิเทศศาสตร์ หรือสาขาอื่นที่เกี่ยวข้องจากสถาบันการศึกษาที่ ก.พ.รับรอง",
    "วันเริ่มสมัคร": "2026-07-21",
    "วันหมดสมัคร": "2026-08-07",
    "วันสอบ": "",
    "วันสัมภาษณ์": "",
    "ลิงก์": "https://personnel.nida.ac.th/job/",
    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10721.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/10070.png",
    "คุณสมบัติเฉพาะ": "รายละเอียดตามประกาศที่แนบ",
    "รายละเอียดงาน": "1. จัดหา คัดเลือก วิเคราะห์ จำแนกหมวดหมู่ทรัพยากรสารสนเทศ ประเภทสื่อสิ่งพิมพ์ สื่อโสตทัศน์ และสื่ออิเล็กทรอนิกส์ ทำรายการบรรณานุกรม ดรรชนี สาระสังเขป และบันทึกลงฐานข้อมูล ระบบห้องสมุดอัตโนมัติ เพื่อเป็นแหล่งจัดเก็บและให้บริการ 2. ศึกษา ค้นคว้า วิธีการและเทคนิคใหม่ ๆ การใช้เครื่องมืออุปกรณ์ที่ทันสมัย ด้านบรรณารักษศาสตร์และสารนิเทศศาสตร์ เพื่อเสนอแนะปรับปรุงการปฏิบัติงานห้องสมุด ทั้งด้านวิชาการ และการให้บริการ 3. จัดทำสื่อประชาสัมพันธ์การใช้ห้องสมุดและจัดกิจกรรมในรูปแบบต่าง ๆ เพื่อเผยแพร่ข้อมูลข่าวสาร และส่งเสริมให้ผู้ใช้เกิดความสนใจในการเข้าใช้บริการ 4. วางแผนการทำงานที่รับผิดชอบ ร่วมดำเนินการวางแผนการทำงานของหน่วยงานหรือโครงการ เพื่อให้การดำเนินงานเป็นไปตามเป้าหมายและผลสัมฤทธิ์ที่กำหนด 5. ประสานการทำงานร่วมกันทั้งภายในและภายนอกทีมงานหรือหน่วยงาน เพื่อให้เกิดความร่วมมือและผลสัมฤทธิ์ตามที่กำหนด 6. ชี้แจงและให้รายละเอียดเกี่ยวกับข้อมูล ข้อเท็จจริง แก่บุคคลหรือหน่วยงานที่เกี่ยวข้อง เพื่อสร้างความเข้าใจหรือความร่วมมือในการดำเนินงานตามที่ได้รับมอบหมาย 7. ให้คำแนะนำ ตอบคำถามเกี่ยวกับข้อมูล และการใช้ทรัพยากรสารสนเทศในห้องสมุดเพื่อให้เกิดความสะดวกแก่ผู้ใช้บริการ 8. การให้บริการพื้นที่การเรียนรู้ 9. ตรวจรูปแบบวิทยานิพนธ์/การค้นคว้าอิสระ 10. งานอื่น ๆ ตามที่ได้รับมอบหมาย",
