    "รายละเอียดงาน": "ลักษณะงานที่ปฏิบัติ มีรายละเอียดดังนี้ 1. ศึกษาและทบทวนการปฏิบัติงานด้านดับเพลิงเพื่อให้เป็นไปตามหลักวิธีการ และมาตรฐาน ขององค์การการบินพลเรือนระหว่างประเทศ 2. ศึกษาโครงสร้างพื้นฐานของอากาศยานทุกแบบที่ใช้บริการ ณ ท่าอากายาน เช่น ช่องทางเข้า - ออก ประตูฉุกเฉิน ช่องเก็บแบตเตอรี่ เป็นต้น เพื่อเตรียมใช้วางแผนในการกู้ภัย 3. ดำเนินการกู้ภัยทุกชนิดที่เกิดขึ้นภายในบริเวณท่าอากาศยานและเขตรับผิดชอบ 4. ดับเพลิงอากาศยานและเพลิงอื่น ๆ ที่เกิดขึ้นภายในบริเวณท่าอากาศยานและเขตรับผิดชอบ โดยใช้เครื่องมืออุปกรณ์ชนิดต่าง ๆ ประจำรถดับเพลิงที่เป็นระบบไฟฟ้าผสมไฮดรอลิกและอิเล็กทรอนิกส์เคมีเพลิง โดยใช้สารดับเพลิงประเภทน้ำยาโฟม รวมทั้งระบบเครื่องยนต์เพื่อการดับเพลิงและกู้ภัย 5. ช่วยพื้นคืนชีพและปฐมพยาบาลผู้ประสบภัยภายในบริเวณท่าอากาศยานและเขตรับผิดชอบ 6. ประสานงานกับหน่วยงานต่าง ๆ ที่เกี่ยวข้องทั้งภายในท่าอากาศยานและภายนอกเขตท่าอากาศยานเพื่อปฏิบัติงานช่วยเหลือด้านสาธารณภัย กรณีได้รับการร้องขอ 7. จัดทำแผนรองรับเพื่อใช้ฝึกซ้อมดับเพลิงและกู้ภัยอากาศยาน ซักซ้อมแผน และเสนอแนะแนวทาง แก้ไขปัญหาต่าง ๆ 8. ดูแลรักษาอุปกรณ์และเครื่องใช้ในการกู้ภัยและดับเพลิงให้อยู่ในสภาพพร้อมใช้งานได้เสมอ 9. ปฏิบัติงานร่วมกับหรือสนับสนุนการปฏิบัติงานของหน่วยงานอื่นที่เกี่ยวข้องหรือที่ได้รับมอบหมาย",
