    "คุณสมบัติเฉพาะ": "รายละเอียดตามประกาศที่แนบ",
    "รายละเอียดงาน": "1. รับผิดชอบดำเนินงานที่เกี่ยวข้องกับการรับรองมาตรฐาน AACSB โดยงานจะเกี่ยวข้องกับการดำเนินกิจกรรมการ เก็บข้อมูล และการเตรียมรายงานตาม Standards ใน AACSB Global Standards for Business Education (Lastest Version) เช่น - การดำเนินและติดตามแผนกลยุทธ์ของคณะ (Standard 1) - การริเริ่มและดำเนินกิจกรรมที่จำเป็น เพื่อให้แผนกลยุทธ์บรรลุผล การติดตามและประเมินผลของแผนกลยุทธ์ -การดำเนินการที่เกี่ยวข้องกับการบริหารหลักสูตร (standard 4) เช่น การปรับปรุงหลักสูตร การวิพากษ์หลักสูตร - การดำเนินการในเรื่องของ AOL (standard 5) เช่น การออกแบบการเก็บข้อมูล การคำนวณค่าเพื่อใช้ ใน CIR report การดำเนินการ Close the loop กิจกรรมอื่นๆ ตามมาตรฐาน ดูเอกสารประกอบ 1. AACSB Global Standards for Business Education (Latest Version) 2. Interpretive Guidance (Latest Version) 2. รับผิดชอบดำเนินงานที่เกี่ยวข้องกับการรับรองมาตรฐาน EQUIS ของ EFMD 3. ประสานงานกับบริษัท QED ในการจัดทำ Gap Analysis และ Data Sheet เพื่อเตรียมตัวในการสมัครเพื่อขอ การรับรองตามมาตรฐานของ EFMD 4. ออกแบบการรวบรวมข้อมูลของคณะทั้งหมดที่ควรจะต้องมีเพื่อใช้ในการรายงานต่อ AACSB โดยปัจจุบัน จะใช้ระบบการเก็บข้อมูลของบริษัท H2 Solutions การเก็บข้อมูลจะคลอบคลุมข้อมูลจากฝ่ายต่างๆ ที่มีอยู่แล้วหรือข้อมูลอื่นๆ ที่ควรจะต้องเก็บเพิ่มขึ้นเพื่อใช้ประโยชน์ในการดำเนินการของ AACSB และ EFMD 5. การเขียนรายงานที่เกี่ยวข้องกับการขอรับรองมาตรฐานของ AACSB และ EFMD 6. การเข้าร่วมสัมมนาทั้งแบบ On site และ Online ที่เกี่ยวข้อง 7. งานอื่นๆ ที่คณะมอบหมาย",
