    "รายละเอียดงาน": "1. ควบคุมการทำงานของเครื่องคอมพิวเตอร์ 2. ติดตามและปรับปรุงข้อมูลให้ถูกต้อง ครบถ้วน ทันสมัย ใช้และซ่อมเครื่องคอมพิวเตอร์ และแก้ไขขั้นต้นเกี่ยวกับเครื่องคอมพิวเตอร์ และอุปกรณ์ที่เกี่ยวข้อง 3. ดูแลและบำรุงรักษาเครื่องคอมพิวเตอร์ และอุปกรณ์ต่าง ๆ ที่เกี่ยวข้อง 4. ปฏิบัติงานอื่นที่เกี่ยวกับการซ่อมเครื่องคอมพิวเตอร์ และอุปกรณ์ที่เกี่ยวข้อง ภายใต้การควบคุมของผู้บังคับบัญชา 5. ปฏิบัติงานอื่นที่เกี่ยวกับราชการ หรือตามที่ผู้บังคับบัญชามอบหมาย",
