    "คุณสมบัติเฉพาะ": "ได้รับคุณวุฒิประกาศนียบัตรวิชาชีพ (ปวช.) ในทุกสาขา",
    "รายละเอียดงาน": "1. ปฏิบัติภารกิจด้านการใช้วิชาการทางด้านสถิติ เช่น การกำหนดมาตรฐานสถิติ กำหนดระเบียบวิธีและควบคุมคุณภาพเชิงสถิติ และเทคนิคการปฏิบัติทางการสถิติ การวางแผนจัดการสถิติ รวมทั้งการดำเนินการส่งเสริมวิชาการทางด้านสถิติ และปฏิบัติหน้าที่เกี่ยวข้อง โดยมีคู่มือหรือแนวปฏิบัติหรือคำสั่งอย่างกว้าง ๆ และอยู่ภายใต้การกำกับตรวจสอบเฉพาะกรณีที่จำเป็น 2. ปฏิบัติงานสนามเก็บรวบรวมข้อมูลในพื้นที่จังหวัดพังงาได้ทุกอำเภอ ตำบล หมู่บ้าน มีทักษะการใช้เครื่อง Tablet และคอมพิวเตอร์ 3. ปฏิบัติภารกิจหรือประสานงานกับหน่วยงานของรัฐและเอกชนที่เกี่ยวข้องกับการพัฒนาด้านดิจิทัล เพื่อพัฒนาเป็นจังหวัดที่มีศักยภาพในการให้บริการภาครัฐ ที่ประชาชนสามารถเข้าถึงได้ ด้วยเทคโนโลยีดิจิทัล 4. ปฏิบัติภารกิจเพื่อสนับสนุนการขับเคลื่อนนโยบายที่สำคัญตามนโยบายของกระทรวงดิจิทัลเพื่อเศรษฐกิจและสังคม 5. ปฏิบัติหน้าที่อื่นตามที่ได้รับมอบหมายเพื่อสนับสนุนภารกิจหลักและภารกิจอื่น ๆ ของสำนักงานฯ",
