    "วันเริ่มสมัคร": "2026-08-26",
    "วันหมดสมัคร": "2026-09-03",
    "วันสอบ": "",
    "วันสัมภาษณ์": "",
    "ลิงก์": "https://www4.fisheries.go.th/personnel-recruitment",
    "ไฟล์ประกาศ": "https://job.ocsc.go.th/upload2/job-10822.pdf",
    "โลโก้หน่วยงาน": "https://job.ocsc.go.th/content/accreditation/departments/071.png",
    "คุณสมบัติเฉพาะ": "ผู้สมัครสอบต้องได้รับคุณวุฒิปริญญาตรี จากสถาบันการศึกษาที่ ก.พ. รับรอง ดังนี้ 1. สาขาวิชาใดสาขาวิชาหนึ่ง ทางการอาหาร ทางพัฒนาผลิตภัณฑ์อุตสาหกรรม ทางเทคโนโลยีการบรรจุ หรือทางวิศวกรรมอาหาร 2. สาขาวิชาเกษตรศาสตร์ ทางพัฒนาผลิตภัณฑ์อุตสาหกรรม ทางการอาหาร ทางเทคโนโลยีการบรรจุ ทางวิศวกรรมอาหาร ทางวิทยาศาสตร์การอาหาร ทางชีววิทยา ทางผลิตภัณฑ์ประมง ทางผลิตภัณฑ์สัตว์น้ำ ทางพัฒนาผลิตภัณฑ์ ทางอุตสาหกรรมการเกษตร ทางเทคโนโลยีการพัฒนาผลิตภัณฑ์ หรือทางวิทยาศาสตร์และเทคโนโลยีการอาหาร 3. สาขาวิชาวิทยาศาสตร์ชีวภาพ ทางชีววิทยา ทางจุลชีววิทยา ทางชีววิทยาประยุกต์ ทางชีววิทยาทั่วไป ทางชีวเคมี หรือทางวิทยาศาสตร์ชีวภาพ 4. สาขาวิชาวิทยาศาสตร์กายภาพ ทางชีวเคมี ทางเคมีวิเคราะห์ หรือทางเคมี",
    "รายละเอียดงาน": "ปฏิบัติงานศึกษา ทดลอง วิจัยด้านการแปรรูปสัตว์น้ำให้เป็นผลิตภัณฑ์อาหารชนิดต่าง ๆ รวมทั้งการพัฒนา การบรรจุและบรรจุภัณฑ์ เพื่อปรับปรุงกรรมวิธีในการแปรรูปสัตว์น้ำของชาวประมงและโรงงานอุตสาหกรรมสัตว์น้ำให้มีประสิทธิภาพ ศึกษาวิเคราะห์หาความสดและคุณภาพของสัตว์น้ำ ปรับปรุงวิธีการดูแลรักษา การขนส่ง การบรรจุ และการเก็บรักษาสัตว์น้ำ เพื่อรักษาคุณภาพสัตว์น้ำให้เป็นไปตามมาตรฐาน วิเคราะห์คุณภาพสัตว์น้ำและผลิตภัณฑ์ทางด้านกายภาพ เคมี และจุลินทรีย์ เพื่อการรับรองคุณภาพ และเป็นไปตามมาตรฐานของประเทศ หรือมาตรฐานระดับสากล ตรวจสอบสุขลักษณะสถานแปรรูปสัตว์น้ำ แหล่งขนถ่าย และสถานประกอบการอื่น ๆ ที่เกี่ยวข้อง เพื่อการรับรองตามมาตรฐาน GMP และ/หรือระบบคุณภาพ HACCP วิเคราะห์ วิจัย และประเมินผลเกี่ยวกับงานด้านผลิตภัณฑ์สัตว์น้ำและระบบควบคุมตรวจสอบที่มีความซับซ้อนเพื่อให้เกิดผลสัมฤทธิ์ของงานวิจัยและพัฒนาศักยภาพของตน และปฏิบัติงานอื่น ๆ ที่เกี่ยวข้องตามที่ได้รับมอบหมายและปฏิบัติงานอื่น ๆ ที่เกี่ยวข้องตามที่ได้รับมอบหมาย",
    "แหล่งที่มา": "job.ocsc.go.th",
