    "คุณสมบัติเฉพาะ": "ได้รับปริญญาตรีหรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกัน ในทุกสาขาวิชา ตามที่สำนักงาน ก.พ. กำหนด",
    "รายละเอียดงาน": "ปฏิบัติงานเกี่ยวกับการจัดทำคำขอเสนอของบประมาณรายจ่ายประจำปี ปรับปรุงฐานข้อมูลงบประมาณการรายจ่ายล่วงหน้าระยะปานกลาง จัดทำประมาณการรายจ่ายขั้นต่ำที่จำเป็น จัดทำประมาณการรายได้ประจำปี จัดทำแผนความต้องการงบลงทุนเบื้องต้น จัดทำรายงานการวิเคราะห์ความเสี่ยงตามหลักธรรมาภิบาลของแผนงาน/โครงการที่สำคัญตามนโยบายรัฐบาล (สิ่งก่อสร้างที่มีวงเงินงบประมาณสูง) บันทึกข้อมูลโครงการที่สำคัญ ในระบบการวิเคราะห์ความเสี่ยงตามหลักธรรมาภิบาล บันทึกข้อมูล คำเสนอของบประมาณในระบบงบประมาณอิเล็กทรอนิกส์ (e-budgeting) จัดทำเอกสารประกอบการชี้แจงงบประมาณต่อคณะกรรมาธิการวิสามัญพิจารณาร่างพระราชบัญญัติงบประมาณรายจ่ายประจำปีเสนอต่อสภาผู้แทนราษฎร จัดทำเอกสารประกอบการชี้แจงงบประมาณเสนอต่อคณะกรรมาธิการวิสามัญพิจารณาศึกษาร่างพระราชบัญญัติงบประมาณรายจ่ายประจำปีงบประมาณเสนอต่อวุฒิสภา จัดทำเอกสารประกอบการชี้แจงงบประมาณต่อคณะอนุกรรมการแต่ละด้าน จัดทำแผน การปฏิบัติงานและแผนการใช้จ่ายงบประมาณประจำปี เสนอสำนักงบประมาณเพื่อพิจารณาให้ความเห็นชอบเรื่องการจัดสรรงบประมาณและโอนเงินงบประมาณให้หน่วยงาน บันทึกข้อมูลแผนการปฏิบัติงานและแผนการใช้จ่ายงบประมาณในระบบสารสนเทศเพื่อการติดตามและประเมินผล (BB-EvMIS : Evaluation Management Information System) ในขั้นตอนการจัดทำงบประมาณสำหรับเป็นเครื่องมือในการรายงานแผน/ผลการปฏิบัติงานและการใช้จ่ายงบประมาณ จัดสรรงบประมาณรายจ่ายประจำปี ให้ส่วนกลางและส่วนภูมิภาค จัดทำแผนปฏิบัติการจัดซื้อจัดจ้างเสนอสำนักงานตรวจเงินแผ่นดิน และปฏิบัติงานอื่น ๆ ที่ได้รับมอบหมาย",
