    "รายละเอียดงาน": "1.ปฏิบัติภารกิจด้านการใช้วิชาการทางด้านสถิติเช่น การกำหนดมาตรฐานสถิติกำหนดระเบียบวิธี ปฏิบัติและควบคุมคุณภาพเชิงสถิติ และเทคนิคการปฏิบัติทางการสถิติ การวางแผนจัดการสถิติ รวมทั้งการ ดำเนินการส่งเสริมวิชาการทางด้านสถิติและปฏิบัติหน้าที่ที่เกี่ยวข้อง โดยมีคู่มือหรือแนวปฏิบัติคำสั่งอย่างกว้างๆ และอยู่ภายใต้การกำกับตรวจสอบเฉพาะกรณีที่จําเป็น 2.ปฏิบัติงานสนามเก็บรวบรวมขอมูลในพื้นที่จังหวัดระยองได้ทุกอำเภอ ตำบล หมู่บ้าน มีทักษะการใช้ เครื่อง Tablet และคอมพิวเตอร์ 3.ปฏิบัติภารกิจหรือประสานงานกับ หน่วยงานของรัฐและเอกชนที่เีกี่ยวข้องกับการพัฒนาด้านดิจิทัล เพื่อพัฒนาเป็นจังหวัดที่มศักยภาพในการให้บริการภาครัฐ ที่ประชาชนสามารถเข้าถึงได้ด้วยเทคโนโลยีดิจิทัล 4.ปฏิบัติภารกิจเพื่อสนับสนุน การขับเคลื่อนนโยบายที่สำคัญตามนโยบายของกระทรวงดิจิทัลเพื่อเศรษฐกิจ และสังคม 5.ปฏิบัติงานเกี่ยวกับงานธุรการต่าง ๆ เช่น การรับ - ส่งงานในระบบสารบรรณ การจัดทำหนังสือ ราชการต่าง ๆ 6.ปฏบิัติหน้าที่อื่นตามที่ได้รับมอบหมายเพื่อสนับสนุนภารกิจหลักและภารกิจอื่น ๆ ของสำนักงาน สถิติจังหวัดระยอง",
