    "คุณสมบัติเฉพาะ": "(1) ความรู้ทั่วไปเกี่ยวกับสำนักงานการวิจัยแห่งชาติ (2) ความรู้ความเข้าใจเกี่ยวกับงานด้านการเงินและบัญชี ได้แก่ - พระราชบัญญัติวินัยการเงินการคลังของรัฐ พ.ศ. 2561 - พระราชบัญญัติวิธีการงบประมาณ พ.ศ. 2561 - ระเบียบกระทรวงการคลังว่าด้วยการเบิกจ่ายเงินจากคลัง การรับเงิน การจ่ายเงิน การเก็บรักษาเงิน และการนำเงินส่งคลัง พ.ศ. 2562 - การบริหารการเงินการคลังภาครัฐด้วยระบบอิเล็กทรอนิกส์ (GFMIS) - หลักการบัญชีเบื้องต้น",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น ที่ปฏิบัติงานด้านการเงินและบัญชี ตามแนวทาง แบบอย่าง ขั้นตอน และวิธีการที่ชัดเจน ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย",
    "แหล่งที่มา": "job.ocsc.go.th",
    "สถานะ": "เปิดรับ",
