    "คุณสมบัติเฉพาะ": "ได้รับปริญญาตรีหรือคุณวุฒิอย่างอื่นที่เทียบได้ในระดับเดียวกัน ในทุกสาขาวิชา",
    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้น โดยใช้ความรู้ ความสามารถทางวิชาการในการทำงานปฏิบัติงานเกี่ยวกับการบริหารจัดการภายในสำนักงานหรือการบริหารราชการทั่วไป ภายใต้การกำกับ แนะนำ ตรวจสอบ และปฏิบัติงานอื่นตามที่ได้รับมอบหมาย โดยมีลักษณะงานที่ปฏิบัติ ดังนี้ 1. ศึกษา รวบรวมข้อมูล สถิติ สรุปรายงาน เพื่อสนับสนุนการบริหารสำนักงานในด้านต่าง ๆ เช่น งานบริหารทรัพยากรบุคคล งานบริหารงบประมาณ งานบริหารแผนปฏิบัติราชการ งานบริหารอาคารสถานที่ งานสัญญาต่าง ๆ และ/หรืองานรับเรื่องร้องเรียน เป็นต้น 2. ปฏิบัติงานเลขานุการของผู้บริหาร เช่น การกลั่นกรองเรื่อง การจัดเตรียมเอกสารสำหรับการประชุม เป็นต้น เพื่อไม่ให้เกิดข้อผิดพลาดในการวินิจฉัยสั่งการของผู้บริหาร 3. จัดเตรียมการประชุม บันทึกและเรียบเรียงรายงานการประชุม และรายงานอื่น ๆ เพื่อให้การบริหารการประชุมมีประสิทธิภาพและบรรลุวัตถุประสงค์ของหน่วยงาน 4. ทำเรื่องติดต่อกับหน่วยงานและบุคคลต่าง ๆ ทั้งในประเทศและต่างประเทศ เพื่อให้การดำเนินงานบรรลุเป้าหมายตามที่กำหนดไว้ 5. ช่วยติดตามการปฏิบัติตามมติของที่ประชุม หรือการปฏิบัติตามคำสั่งของผู้บริหารของหน่วยงาน เพื่อการรายงานและเป็นข้อมูลประกอบการพิจารณาของผู้บังคับบัญชาต่อไป 6. วางแผนการทำงานของตนเอง ร่วมดำเนินการวางแผนการทำงานของหน่วยงานหรือโครงการ เพื่อให้การดำเนินงานเป็นไปตามเป้าหมาย ผลสัมฤทธิ์ที่กำหนด 7. ประสานการทำงานที่ได้รับมอบหมายให้สอดคล้องกับภาพรวมผลงานของทีมงาน ประสานงาน กับสมาชิกภายในทีมงาน ให้ความช่วยเหลือภายในทีมงาน เพื่อให้ได้ผลสัมฤทธิ์ตามที่กำหนดไว้ 8. ตอบปัญหา ชี้แจง และให้คำแนะนำเกี่ยวกับงานในความรับผิดชอบ ในระดับเบื้องต้นแก่หน่วยงานราชการ เอกชน หรือประชาชนทั่วไป เพื่อให้ผู้ที่เกี่ยวข้องได้ทราบข้อมูลและเกิดความเข้าใจในงานที่รับผิดชอบ 9. งานอื่น ๆ ที่ได้รับมอบหมาย",
