    "รายละเอียดงาน": "ปฏิบัติงานในฐานะผู้ปฏิบัติงานระดับต้นซึ่งไม่จำเป็นต้องใช้ผู้สำเร็จการศึกษาระดับปริญญา ปฏิบัติงานด้านธุรการ สารบรรณ หรือบริการทั่วไป ตามแนวทาง แบบอย่าง ขั้นตอน และวิธีการที่ชัดเจน ในกองด่านอาหารและยา เพื่อสนับสนุน ประสานงานกับหน่วยงานต่าง ๆ ที่เกี่ยวข้องกับกองด่านอาหารและยา ให้เกิดความถูกต้องและบรรลุผลสัมฤทธิ์ของงาน โดยมีลักษณะงานที่ปฏิบัติ ดังนี้ 1. ปฏิบัติงานธุรการ งานสารบรรณ งานบริการทั่วไป เช่น การรับส่ง ลงทะเบียน ร่างหนังสือโต้ตอบจัดเตรียมการประชุม การบันทึกข้อมูล เพื่อสนับสนุนให้งานต่าง ๆ ดำเนินไปได้โดยสะดวกราบรื่นและมีหลักฐานตรวจสอบได้ 2. รวบรวมข้อมูล จัดเก็บข้อมูลสถิติ เอกสาร หลักฐานหนังสือ ตามระเบียบวิธีปฏิบัติเพื่อสะดวกต่อการค้นหา และเป็นหลักฐานทางราชการ 3. ดำเนินการเกี่ยวกับพัสดุ ครุภัณฑ์ของสำนักงาน เพื่อให้มีอุปกรณ์ที่มีคุณภาพไว้ใช้งานและอยู่ในสภาพพร้อมใช้งาน 4. รวบรวมรายงานผลการปฏิบัติงานและข้อมูลต่าง ๆ นำเสนอต่อผู้บังคับบัญชา เพื่อนำไปใช้เสนอแนะและปรับปรุงการปฏิบัติงานต่อไป 5. ติดต่อประสานงานกับบุคคลภายในหน่วยงานเดียวกันหรือหน่วยงานที่เกี่ยวข้อง เพื่อให้การปฏิบัติงานเป็นไปด้วยความราบรื่น 6. ให้บริการข้อมูลแก่ผู้มาติดต่อราชการ เพื่อให้ได้รับข้อมูลที่จะนำไปใช้ประโยชน์ได้ต่อไป 7. ผลิตเอกสารต่าง ๆ เพื่อสนับสนุนการปฏิบัติงานตามภารกิจของหน่วยงาน 8. ปฏิบัติงานอื่น ๆ ตามที่ได้รับมอบหมาย",
